// ramana_te.dart
// Maharishi Ramana quotes and articles (Telugu)

import '../articlesquotes.dart';

final ramanaSaintTe = Saint(
  'raman',
  'మహర్షి రమణ',
  'assets/images/raman.jpg',
  [
    'మీ స్వీయాత్మ సాక్షాత్కారం ప్రపంచానికి మీరు అందించగలిగే అత్యున్నత సేవ.',
    'సృష్టి లేదు, లయం లేదు, విధి లేదు, స్వేచ్ఛా సంకల్పం లేదు, మార్గం లేదు, సాధన లేదు. ఇదే ఆంత్య సత్యం.',
    'సంతోషం మీ స్వభావం. దానిని కోరుకోవడం తప్పు కాదు. లోపల ఉన్నప్పుడు బయట వెతకడం తప్పు.',
    '"నేను ఎవరు?" అనే ప్రశ్న అన్ని ఇతర ప్రశ్నలను నాశనం చేస్తుంది.',
    'తన నిజ స్వరూపాన్ని తెలుసుకోకుండా ప్రపంచాన్ని సరిదిద్దాలని కోరుకోవడం అంటే రాళ్లు, ముల్లు మీద నడిచే బాధను నివారించడానికి ప్రపంచాన్ని తోలు తోడుతో కప్పడం వంటిది.',
    'నిశ్శబ్దత కూడా సంభాషణే.',
    'మనస్సు అనేది ఆలోచనల సమాహారం మాత్రమే. ఆలోచనలు నిలిపివేసి, మనస్సును చూపించు.',
    'ప్రస్తుత జన్మ యొక్క ఏకైక ఉపయోగకరమైన ఉద్దేశ్యం అంతర్ముఖంగా మారి ఆత్మను తెలుసుకోవడం.',
    'ఎవరూ ప్రయత్నం లేకుండా విజయాన్ని సాధించలేరు. విజయం సాధించిన వారు తమ విజయాన్ని పట్టుదలకి అప్పగిస్తారు.',
    'వచ్చేది వచ్చనివ్వు. పోయేది పోనివ్వు. మిగిలేది ఏమిటో తెలుసుకో.',
    '\'నేను ఎవరు?\' అనే ప్రశ్న ఒక సాధారణ మానసిక వ్యాయామం కాదు. ఇది అత్యున్నత రూపంలోని ఆధ్యాత్మిక సాధన.',
    '\'నేను\' అనే ఆలోచన అన్ని ఆలోచనల మూలం. దానిని పట్టుకుని దాని మూలానికి చేరుకోవడం మాత్రమే అన్ని ఆలోచనలను నాశనం చేసే మార్గం.',
    'ఆత్మ ఎల్లప్పుడూ సన్నిహితంగా ఉంటుంది. దానిని వెతకాల్సిన అవసరం లేదు, ఆత్మ కానిది వెతకడం మానుకోవడమే చాలు.',
    'చివరి సత్యం ఇది: \'నేను\' అనే భావన కాదు; అది చైతన్యం స్వయంగా.',
    'ఆత్మను తెలుసుకోవడానికి అవసరమైనది నిశ్చలంగా ఉండటం మాత్రమే.',
    'నీవు ఆత్మవు. ఆత్మగా ఉండు.',
    '\'నేను ఎవరు?\' అని అడగడం అనేది మనస్సును లోపలికి తిప్పి మూలానికి లోతుగా మునిగిపోవడం.',
    'పాము కేవలం కట్టెలోనే కనిపించేది, అహంకారం కేవలం ఆత్మలోనే కనిపిస్తుంది.',
    'అహంకారం మనస్సు. మనస్సే అన్ని ఆకాంక్షల మూలం.',
    'అహంకారం నిజమైన సత్యం కాదు. అది ఒక ఆలోచన రూపం, ఆత్మ యొక్క వెలుగు ప్రకాశించినప్పుడు అదృశ్యమయ్యే నీడ.',
    'మనస్సు ఒక మాయ. అది ఆలోచనల సమాహారం మాత్రమే.',
    'మనస్సు శాంతించగానే ఆత్మ అనుభవం అవుతుంది. మనస్సే అడ్డంకి.',
    'అవగాహన అనేది కొత్తగా పొందినది కాదు. అది నీ శాశ్వత స్వభావాన్ని పునఃసంధానం చేయడం.',
    'శరీరం మరియు మనసు మీరు కాదు. మీరు ఈ రెండింటికి సాక్షిగా ఉన్నవారు.',
    '\'నేను\' అనే ఆలోచన తొలగినప్పుడు, అన్ని ఇతర ఆలోచనలు కూడా దానితో కలిసి తొలగిపోతాయి.',
    'నిశ్శబ్దతే ఆధ్యాత్మిక బోధనలో అత్యంత శక్తివంతమైన రూపం.',
    'ఉత్తమ ఆధ్యాత్మిక సాధన శాంతంలో నిలిచి ఉండటమే.',
    'అవగాహన అనేది పొందవలసినది కాదు; అది ఆలోచనల లేమిలో వెలుగులోకి రావలసినది.',
    'హృదయపు నిశ్శబ్దం ఏ మాటకన్నా ఎక్కువ భావప్రధానం.',
    'నిజమైన జ్ఞానం బుద్ధిలో కాదు; అది హృదయంలో ఉంటుంది, మరియు అది నిశ్శబ్దంలో వెలుగులోకి వస్తుంది.',
    'చివరి స్థితి నిశ్శబ్ద స్థితి, అక్కడ \'నేను\' లేదా \'నువ్వు\' అనే భావం ఉండదు.',
    'ఆత్మను సంపూర్ణ నిశ్శబ్దతలో అనుభవించవచ్చు.',
    'నిశ్చలంగా ఉండటం అత్యున్నతమైన ప్రార్థన.',
    'నిజమైన శాంతి అనేది అన్ని ఆలోచనల లేమి.',
    'ధ్యానం అనేది దేవుని గురించి ఆలోచించడం కాదు, కానీ ఆ నిశ్చలత స్థితిలో ఉండటం, అదే దేవుడు.',
    'మనసు ఒక చంచలమైన కోతి. దాన్ని శాంతపరచడానికి ఏకైక మార్గం నిశ్చలంగా ఉండటం.',
    'నిశ్శబ్దం ఆత్మ యొక్క నిత్యస్థితి.',
    'మీరు నిశ్శబ్దంలో ఎంత ఎక్కువగా ఉంటే, నిజాన్ని అంత ఎక్కువగా గ్రహిస్తారు.',
    'నిశ్శబ్దం అనేది శబ్దం లేని స్థితి కాదు, అది నిశ్చలత యొక్క సాన్నిధ్యం.',
    'నిజమైన ప్రార్థన అంటే నిశ్చలంగా ఉండి \'నేనే\' అని తెలుసుకోవడం.',
    'దేవుడు బాహ్యమైన వ్యక్తి కాదు. దేవుడు ఆత్మ.',
    'ప్రపంచం మాయ. ఆత్మ మాత్రమే నిజం.',
    'మీరు చూసే ప్రతిదీ దైవమే. మీరు వినే ప్రతిదీ దైవమే.',
    'లోకం మనస్సు ప్రతిఫలనం మాత్రమే.',
    'ఆత్మ తప్ప వాస్తవం మరేదీ లేదు.',
    'ప్రపంచం మీ నుండి వేరుగా ఉన్నది కాదు.',
    'ప్రపంచం మీలో ఉంది, మీరు ప్రపంచంలో లేరు.',
    'ఏకైక నిజం ఆత్మ. లోకం, అహంకారం, దేవుడు అన్నీ ఆత్మలోనే ఉన్నాయి.',
    'ప్రపంచం ఒక స్వప్నం. ఆ స్వప్నదృష్టి ఆత్మ.',
    'దేవుడు అన్నిటికీ మూలం, అన్నింటికీ సాక్షి, అన్నింటి నిజస్వరూపం.',
    'ఒకే ఒక వాస్తవం ఉంది, అది చైతన్యం.',
    'దేవుడు ప్రేమ. ప్రేమ ఆత్మ యొక్క వెలుగు.',
    'ప్రపంచం ఒక ఆలోచన మాత్రమే. ఏకైక నిజం ఆత్మ.',
    'ప్రపంచం భగవంతుని ఆవిర్భావం, కానీ భగవంతుడు ప్రపంచంతో పరిమితం కాదు.',
    'ఆత్మ సర్వసత్త్వాల ఆధారభూతం.',
    'కార్యం బంధానికి కారణం కాదు; కర్తృత్వ భావమే కారణం.',
    'నిజమైన చర్య నిరంతరాయంగా, సహజస్ఫూర్తిగా ఉద్భవిస్తుంది. అది ఆత్మస్థితి నుండి ప్రవహిస్తుంది.',
    'మీ క్రియల ఫలితాల గురించి ఆందోళన చెందకండి. ఆత్మ అన్నింటినీ చూసుకుంటుంది.',
    'కర్తృత్వ భావం లేకుండా చేసిన కర్మ మోక్షానికి దారితీస్తుంది.',
    'కర్మ కారణ-ప్రభావాల శృంఖలమే, కానీ ఆత్మ కర్మ నుండి విముక్తి పొందినది.',
    'లోకంలో నివసించు, కానీ లోకానికి చెందకుండా ఉండు.',
    'కర్మ నుండి విముక్తి పొందడానికి ఏకైక మార్గం ఆత్మను తెలుసుకోవడం.',
    'ఫలితాలపై ఆసక్తి లేకుండా మీ కర్తవ్యాలను నిర్వర్తించండి.',
    'దైవ చిత్తానికి శరణాగతి పొందితే, మీ అన్ని కర్మలు సులభంగా జరుగుతాయి.',
    'ఆత్మను గ్రహించినవారికి కర్మ లేదు.',
    'మీ ఇంద్రియాలకు లేదా కోరికలకు బానిసలుగా ఉండకండి.',
    'మీరు ఇతరులకు ఎంత ఎక్కువ సేవ చేస్తారో, అంత ఎక్కువగా మీరు వారిలోని ఆత్మను గుర్తిస్తారు.',
    'అన్ని క్రియలకు సాక్షిగా ఉండటం అత్యున్నత క్రియారూపం.',
    'చింతన ఫలితమే క్రియ. నిశ్శబ్దం ఈ రెండింటి లేమి.',
    'ప్రపంచం ఒక వేదిక. మీ పాత్రను ఆడండి, కానీ మీరు ఎవరో మరచిపోకండి.',
    'గురు వ్యక్తి కాదు. గురువు ఆత్మ.',
    'గురు మీలోనే ఉన్నారు. గురువు అంతరాత్మ స్వరం.',
    'నిజమైన గురువు నిన్ను ఆత్మసాక్షాత్కారం వైపు నడిపించే వాడు.',
    'గురువు కృప ఎప్పుడూ ఉంటుంది. దాన్ని స్వీకరించడం మీపై ఆధారపడి ఉంటుంది.',
    'మీ గురువును గౌరవించడానికి ఉత్తమ మార్గం ఆత్మను తెలుసుకోవడం.',
    'గురు మీ నిజమైన ఆత్మను చూసే అద్దంలాంటివారు.',
    'ఆత్మసాక్షాత్కారానికి గురుకృప అవసరం.',
    'గురు శరీరం కాదు. గురువు అన్నీ హృదయాలలో నివసించే చైతన్యం.',
    'గురు ఒక మార్గదర్శి, కాని భోగసమృద్ధి కర్త కాదు.',
    'గురువు కృప అనేది మీ నావను నడిపించే గాలి. మీ ప్రయత్నం ఆ నావలోని తెర.',
    'గురువుపై విశ్వాసం ఉంచండి, గురువు మీకు సత్యాన్ని చూపిస్తారు.',
    'గురు సత్యానికి జీవంత ప్రతిరూపం.',
    'గురు మీ నుండి వేరుగా లేరు. మీరు గురువుతో ఏకత్వంలో ఉన్నారు.',
    'గురువు బోధన నిశ్శబ్దంగా ఉండటం.',
    'గురు మనస్సు దాటి వెళ్లడానికి సహాయపడే వాడు.',
    'మనస్సు అనేది క్రియాశీలమైన అహంకారం.',
    'అహంకారం అనేది \'నేను ఈ శరీరమే\' అనే భావన.',
    'అహంకారం నశించినప్పుడు, ఆత్మ ప్రకాశిస్తుంది.',
    'ఆత్మసాక్షాత్కారానికి అడ్డుకట్టగా నిలిచేది అహంకారమే.',
    'అహంకారం అనేది ఆలోచనలు, భావాలు, మరియు జ్ఞాపకాలు అనే సంగ్రహం.',
    'మనస్సు ఒక అందమైన సేవకుడు, కానీ ఒక ప్రమాదకరమైన యజమాని.',
    'మోక్షం ఎక్కడికైనా వెళ్లడం గురించి కాదు. ఇది ఇక్కడ, ఇప్పుడే ఉండటం గురించి.',
    'అహంకారాన్ని నశింపజేయడానికి ఏకైక మార్గం ఆత్మకు శరణు పొందడం.',
    'మనసు మహా మోసగాడు. అది వేరుగా ఉన్న స్వరూపం అనే మాయను సృష్టిస్తుంది.',
    'అహంకారం అనేది భయాలు మరియు కోరికలతో నిర్మించిన కోట.',
    'మనస్సు నుండి విముక్తి పొందినప్పుడే నిజమైన స్వేచ్ఛ పొందినవాడవుతాడు.',
    'మనసు ఒక అద్దం వంటిది. మీరు అందులో చూసేది మీ ఆలోచనల ప్రతిబింబం.',
    'మనస్సే అన్ని కష్టాలకు కారణం. ఆత్మే సర్వానందానికి మూలం.',
    'అహంకారమే అన్ని సమస్యలకు మూలం. \'నేను కోరుకుంటున్నాను\' అని చెప్పేది అదే.',
    'మనసు ఒక స్వప్న యంత్రం. ఇది ప్రపంచాన్ని మరియు దాని అన్ని మాయలను సృష్టిస్తుంది.',
    'మనస్సు ఒక నది. ఆత్మ సముద్రం.',
    'మోక్షం అనేది ఒక గమ్యం కాదు, అది ఒక స్థితి.',
    'మనస్సు ఒక సాధనం. దాన్ని ఉపయోగించే వాడు నీవే.',
    'అహంకారం మనం మనకు చెప్పుకునే కథ.',
    'మనస్సు ఒక జైలు. ఆత్మనే తాళం చెవి.',
    'మనస్సు ఆత్మ సూర్యుడిని కప్పివేసే మేఘం.',
    'అహంకారం తాత్కాలిక మాయ. ఆత్మ శాశ్వత సత్యం.',
    'మనస్సు అతిథి. ఆత్మ ఆతిథ్యదాత.',
    'మోక్షం అనేది సంపూర్ణ నిశ్శబ్దత మరియు శాంతి స్థితి.',
    'నిజమైన స్వేచ్ఛను పొందడానికి ఏకైక మార్గం మీరు మీరుగా ఉండటమే.',
    '\'నేను ఎవరు?\' అనే ప్రశ్నకు సమాధానం పొందడం కోసం కాదు. ఆ ప్రశ్నే సమాధానం. \'నేను\' అనే ఆలోచన యొక్క మూలాన్ని నిరంతరం పరిశీలించడం ద్వారా, తప్పుడు \'నేను\' నశించి, నిజమైన ఆత్మ స్వయంగా ప్రకాశిస్తుంది.',
    'మీ ధర్మం ఉండటమే కానీ ఇది లేదా అది కావడం కాదు. \'నేను నేను\' అనే వాక్యం మొత్తం సత్యాన్ని సంక్షిప్తంగా చెప్పుతుంది. ఆ విధానం \'నిశ్చలంగా ఉండు\' అనే మాటలో ఉంది. నిశ్చలత అంటే ఏమిటి? అది \'నీ ఆత్మను నాశనం చేయు\' అని అర్థం, ఎందుకంటే ప్రతి పేరు మరియు రూపం సమస్యకు కారణం.',
    'ఆత్మ ఎల్లప్పుడూ ఉంది. అది నీవే. దానిని పొందాల్సిన అవసరం లేదు, గ్రహించాల్సిన అవసరం లేదు. మనం ఆత్మ కాదనే తప్పుడు భావనను మాత్రమే వదిలించుకోవాలి.',
    'ఎంతకాలం వ్యక్తిత్వం అనే భావన ఉంటుందో, అంతకాలం లోకం మరియు దేవుడు అనే భావనలు కూడా ఉంటాయి. వ్యక్తిత్వం నశించినప్పుడు, మిగతా అన్నీ కూడా అదృశ్యమవుతాయి.',
    'సంతోషం మీ స్వభావం. సంతోషం కోరుకోవడం తప్పు కాదు. లోపల ఉన్నప్పుడు బయట వెతకడం తప్పు.',
    'మనస్సు అనేది ఆలోచనల గుత్తి. \'నేను\' అనే ఆలోచన వాటి మూలం. ఆ మూలాన్ని తీసివేస్తే, మిగతావన్నీ వేరుపడతాయి.',
    'మనస్సు నిలిచిపోయినప్పుడు ఆత్మ అనుభవించబడుతుంది. మనస్సు ఉన్నంతవరకు సందేహం మరియు బాధ ఉంటాయి.',
    'నిశ్శబ్దం అత్యంత శక్తివంతమైన ఉపదేశం. అది ఉత్తమమైన భాష. నిశ్శబ్దంలో అన్ని సందేహాలు నివృత్తి అవుతాయి.',
    'ఆత్మ అనేది చేరుకోవలసినది కాదు. మీరు ఎప్పుడూ ఆత్మనే. దానిని చేరడం లేదు. కేవలం అజ్ఞానాన్ని తొలగించడం మాత్రమే ఉంది.',
    'మనస్సు లోపలికి తిరిగి తన స్వభావాన్ని పరిశీలించినప్పుడు, అది అదృశ్యమవుతుంది, మరియు మిగిలేది ఆత్మ మాత్రమే.',
    'మనమే నిజస్వరూపం అయినప్పటికీ, నిజాన్ని పొందాలని తపించటం కన్నా గొప్ప రహస్యం మరొకటి లేదు.',
    'శరీరమే ఒక ఆలోచన. లోకమూ ఒక ఆలోచనే. మనస్సు లీనమైతే, అన్ని ఆలోచనలు లీనమవుతాయి.',
    'కృప ఎల్లప్పుడూ ఉంటుంది. అది కొత్తగా పొందవలసినది కాదు. కృప ఆత్మనే.',
    'ఆత్మసాక్షాత్కారానికి అడ్డుగా నిలిచే అత్యంత పెద్ద అడ్డంకి, అది పొందవలసిన లక్ష్యమని భావించడమే.',
    'ఆత్మను గ్రహించడానికి ప్రయత్నించకండి. దాన్ని గ్రహించడంలో అడ్డంకులైన వాటిని తొలగించడానికి మాత్రమే ప్రయత్నించండి.',
    'మనసు మనసును చంపలేడు. మనసు లోపలికి తిరిగి, దాని మూలంలో లీనమయ్యేప్పుడు మాత్రమే అది మరణిస్తుంది.',
    'ఆత్మవిచారణ అనేది \'నేను ఎవరు?\' అనే మంత్రాన్ని పునరావృతం చేయడం కాదు. అది \'నేను\' అనే భావనపై దృష్టిని నిలిపి, దాని మూలాన్ని కనుగొనేవరకు పరిశీలించడమే.',
    'అహంకారం కేవలం ఒక నీడ మాత్రమే. దానిని అన్వేషించినప్పుడు, అది అదృశ్యమవుతుంది.',
    'అహంకారం లయమైనపుడు మిగిలేది ఆత్మ, అది ఆనందమే.',
    'అవగాహన అనే దాని అసలు ఉనికి లేదు. ఉన్నది కేవలం అజ్ఞానాన్ని పోగొట్టుకోవడమే.',
    'ఆత్మ ఎల్లప్పుడూ సాక్షాత్కారమై ఉంటుంది. అడ్డంకి ఆందోళనతో కూడిన మనస్సు.',
    'నిశ్శబ్దంగా ఉండటం నేర్పు-జ్ఞానం అని పిలుస్తారు.',
    'మీరు ఏదైనా చేయవచ్చు, కానీ \'నేను\' అనే భావనను పరిశీలించాలి. అదే మార్గం.',
    'మీరు ఆత్మగా, ఆలోచనల నుండి విముక్తిగా ఉండగలిగితే, అన్ని సమస్యలు స్వయంగా పరిష్కారమవుతాయని మీరు గ్రహిస్తారు.',
    '\'నేను\' అనే భావం శరీరంలో ఉద్భవిస్తుంది, కానీ అది శరీరానికి చెందినది కాదు.',
    'బయటకు తిరిగే మనస్సు ఆలోచనలు మరియు వస్తువులను సృష్టిస్తుంది. లోపలికి తిరిగే మనస్సు ఆత్మగా మారుతుంది.',
    'ప్రపంచం మీ వెలుపల లేదు. ప్రపంచం మనసు యొక్క ప్రతిబింబం మాత్రమే.',
    'మనస్సు ప్రశాంతంగా ఉంటే, ప్రపంచం కూడా ప్రశాంతంగా కనిపిస్తుంది.',
    'మనస్సును నియంత్రించడం కాదు, దాని స్వభావాన్ని అన్వేషించడమే అవసరం.',
    'ఒకవేళ \'నేను శరీరం\' అని భావిస్తూనే ఉంటే, బాధ నుండి తప్పించుకోలేరు.',
    'ఆత్మను బుద్ధి ద్వారా తెలుసుకోలేము. బుద్ధి శాంతించినప్పుడు అది స్వయంగా ప్రత్యక్షమవుతుంది.',
    '\'నేను\' అనే భావం ఆగినప్పుడు, ఆత్మ మాత్రమే మిగులుతుంది.',
    '\'నేను\' అనే ఆలోచన ఒక దొంగ పోలీసు వేషం వేసుకున్నట్టుగా ఉంటుంది.',
    'ఆత్మ రాదు, పోదు. కేవలం ఆలోచనలు మాత్రమే వచ్చి పోతాయి.',
    'సాక్షాత్కార స్థితి సహజ స్థితి.',
    'మీరు లోకాన్ని త్యజించాల్సిన అవసరం లేదు. లోకాన్ని వేరుగా చూస్తున్న అహంకారాన్ని త్యజించండి.',
    'శరీరం మరియు మనస్సు సాధనాలు మాత్రమే. మీరు అవి కాదు.',
    'స్వేచ్ఛ బయట కనిపించదు. స్వేచ్ఛ అబద్ధమైన \'నేను\' నుండి విముక్తి.',
    'ఆత్మను ఒక వస్తువుగా అనుభవించలేము. అది అనుభవించేవాడు.',
    'విచారణ నిశ్శబ్దానికి దారి తీస్తుంది, నిశ్శబ్దం సత్యాన్ని వెల్లడిస్తుంది.',
    'విషయాలకు ఆసక్తి ఉన్న మనస్సు బంధితమై ఉంటుంది. అసక్తి లేని మనస్సు స్వేచ్ఛగా ఉంటుంది.',
    'ప్రయత్నం మరియు కృప మధ్య ఎలాంటి తేడా లేదు.',
    'మీరు పూర్తిగా సమర్పించుకుంటే, ప్రశ్నలు అడిగే ఎవరూ మిగలరు.',
    'స్వీయ పరిశీలనే ఉత్తమ శాస్త్రం.',
    'ఆత్మ మాత్రమే సత్యం. మిగతావన్నీ మాయ.',
    'అహంకారం వస్తువులతో ఐక్యత ద్వారా జీవిస్తుంది. ఐక్యత ఆగినప్పుడు, అహంకారం నశిస్తుంది.',
    'ఆత్మ అంతర్గతమో బాహ్యమో కాదు. అది మాత్రమే సత్యం.',
    'జన్మించినది మరణించాలి. నిజమైనది ఎప్పుడూ జన్మించదు.',
    'ఆత్మస్వరూపంలో నిలిచి ఉండటం ధ్యానం యొక్క అత్యున్నత రూపం.',
    '\'నేను ఎవరు?\' అని ప్రశ్నించడం మనసును లోనికి తిప్పుకోవడం.',
    'కర్తృత్వ భావమే బంధానికి కారణం.',
    'మీరు కర్త కాదు అని తెలుసుకున్నప్పుడు, కర్మలు కొనసాగుతాయి కానీ బంధనం లేకుండా.',
    'శాంతి నీ నిజ స్వభావం.',
    'ఆసక్తి రహితత్వం జ్ఞానం.',
    'ఆత్మకు రక్షణ అవసరం లేదు.',
    'తాత్కాలికమైన వాటితో ఐక్యత చెందడం వల్లనే బాధ ఉత్పన్నమవుతుంది.',
    'ఆత్మ జాగ్రత, స్వప్న, సుషుప్తి స్థితుల సాక్షిగా ఉంటుంది.',
    'నిద్ర ఆనందమయం, ఎందుకంటే అహంకారం లేనప్పుడు.',
    'శాశ్వతమైనది ఎప్పటికీ కోల్పోవడం లేదు.',
    'బయట ఆనందాన్ని వెతుకుతున్న మనసు దానిని ఎప్పటికీ పొందదు.',
    'నిజం చాలా సరళమైనది. మనసు దానిని సంక్లిష్టం చేస్తుంది.',
    'విచారకుడు అన్వేషించబడినవాడు.',
    'అహంకారాన్ని తప్పించి అజ్ఞానం అనే దాని ఉనికి లేదు.',
    'అహంకారం నశించినప్పుడు, ఆత్మ ప్రకాశిస్తుంది.',
    'మనస్సు ఆత్మ నుండి కేవలం ఒక కదలిక దూరంలో ఉంది.',
    'నిశ్చలంగా ఉండి, నీవు ఆత్మవని తెలుసుకో.',
    'ఆత్మ స్వయంప్రకాశమైంది.',
    'విచారణ అజ్ఞానాన్ని నాశనం చేస్తుంది.',
    'ఆత్మ శరీరానికి ఏమి జరిగినా ప్రభావితం కాదు.',
    'విముక్తి భవిష్యత్తులో ఉన్నది కాదు. అది ఇప్పుడే ఉంది.',
    'అహంకారం బంధనాన్ని సృష్టిస్తుంది; ఆత్మ స్వేచ్ఛను ప్రసాదిస్తుంది.',
    'మనస్సు ఆత్మలో విశ్రాంతి పొందినప్పుడు, అదే నిజమైన త్యాగం.',
    'ఆత్మ మాత్రమే నిజమైనది; అహంకారం అసత్యం.',
    'నేను శరీరమే అనే భావననే అసలు అవిద్య.',
    'అన్నీ నిషేధించినపుడు ఆత్మ మాత్రమే నిలిచిపోతుంది.',
    'ధ్యానం అంటే ఆత్మస్వరూపంలో నిలిచిపోవడం.',
    'హృదయం భౌతిక స్థలం కాదు; అది చైతన్యం యొక్క మూలం.',
    'సర్వ సాధనలు మనస్సును ప్రశాంతం చేయడానికే ఉద్దేశించబడ్డాయి.',
    'నిజమైన జ్ఞానం నిశ్శబ్దం.',
    'ఆత్మ ఎప్పుడూ సాక్షాత్కృతమై ఉంటుంది.',
    'నీవు బంధితుడవు కాదు; నీవు బంధితుడనుకుంటున్నావు.',
    '\'నేను\' లయమైతే, ఆత్మ ఉదయిస్తుంది.',
    'ఆత్మ మాత్రమే ఉంది, మరి ఏదీ లేదు.',
    'అవతరణ లేదు. కేవలం సత్తా మాత్రమే ఉంది.',
    'ఆత్మ కాలానికి అతీతం.',
    'ఆత్మను తెలుసుకోవడం అంటే ఆత్మగా ఉండటం.',
    'ఆత్మ శుద్ధమైన అవగాహన.',
    'ఆత్మలో లీనమైన మనస్సు మళ్లీ లేవదు.',
    'పరిశీలన మాత్రమే నేరుగా మార్గం.',
    'అహంకారం ఆత్మ మరియు శరీరం మధ్య గల ముడి.',
    'అహంకారానికి విముక్తి పొందడం నిజమైన స్వేచ్ఛ.',
    'మనస్సు నిలిచినప్పుడు, శాంతి ప్రబలిస్తుంది.',
    'ఆత్మ అనేది తెలుసుకోవలసినది కాదు, అనుభవించవలసినది.',
    'ఆత్మ ఎల్లప్పుడూ సిద్దమైనదే.',
    'అహంకార నశనం ఆత్మ సాక్షాత్కారం.',
    'మీరు ఉన్నట్లుగానే ఉండండి.',
    'అస్తిత్వమే అత్యున్నత బోధ.',
    'ఆత్మ అందరిలోను ఒకటే.',
    'నిజం ఏమిటంటే, మీరు ఇప్పటికే స్వతంత్రులే.',
    'ఆత్మలో నిలిచి ఉండండి, అప్పుడు అన్నీ శ్రేయస్సుగా ఉంటాయి.',
  ],

  [
    Article(
        heading: 'మహర్షి రమణ యొక్క ఉపదేశాలు',
        body: 'సంతోషం\n\nఅన్ని జీవులు ఎప్పుడూ సంతోషాన్ని కోరుకుంటాయి, దుఃఖం లేకుండా ఉన్న సంతోషం. అదే సమయంలో ప్రతి ఒక్కరు తమను తాము అత్యంత ప్రేమిస్తారు. ప్రేమకు కారణం కేవలం సంతోషమే. కాబట్టి, ఆ సంతోషం ఒకదానిలో ఉండాలి. అదనంగా, ఆ సంతోషాన్ని ప్రతి ఒక్కరు నిద్రలో అనుభవిస్తారు, అప్పుడు మనస్సు ఉండదు. ఆ సహజ సంతోషాన్ని పొందాలంటే, మనను తెలుసుకోవాలి. అందుకు, ఆత్మ పరిశీలన, ‘నేను ఎవరు?’ ప్రధాన మార్గం.\n\nచైతన్యం\n\nఅస్తిత్వం లేదా చైతన్యం మాత్రమే నిజమైనది. చైతన్యం మరియు మేల్కొనడం కలిస్తే మేల్కొనడం అని పిలుస్తాము. చైతన్యం మరియు నిద్ర కలిస్తే నిద్ర అని పిలుస్తాము. చైతన్యం మరియు కలలు కలిస్తే కలలు అని పిలుస్తాము. చైతన్యం అనేది అన్ని చిత్రాలు వస్తూ పోయే తెర. స్క్రీన్ నిజమైనది, చిత్రాలు దానిపై కేవలం నీడలు మాత్రమే. \n\nమనస్సు \n\nమనస్సు స్వరూపంలో ఉన్న అద్భుత శక్తి. \n\nఈ శరీరంలో ‘నేను’గా ఉద్భవించేది మనస్సు. \n\nసూక్ష్మమైన మనస్సు మెదడు మరియు ఇంద్రియాల ద్వారా ఉద్భవించినప్పుడు, భౌతిక పేర్లు మరియు రూపాలు గుర్తించబడతాయి. అది హృదయంలో ఉంటే, పేర్లు మరియు రూపాలు కనుమరుగవుతాయి... మనస్సు హృదయంలో ఉంటే, ఆలోచనల మూలం అయిన ‘నేను’ లేదా అహంకారం పోతుంది, మరియు స్వరూపం, నిజమైన, శాశ్వతమైన ‘నేను’ మాత్రమే ప్రకాశిస్తుంది. అహంకారానికి అతి తక్కువ ముద్ర కూడా లేని చోట, స్వరూపం ఉంటుంది. \n\n“నేను ఎవరు?” – విచారణ \n\nఅన్ని ఆలోచనలకు మూలం ‘నేను’ ఆలోచన. \n\nస్వీయ విచారణ ‘నేను ఎవరు?’ ద్వారా మాత్రమే మనస్సు విలీనమవుతుంది. ‘నేను ఎవరు?’ అనే ఆలోచన అన్ని ఇతర ఆలోచనలను నాశనం చేస్తుంది మరియు చివరికి తాన్నే చంపుతుంది. ఇతర ఆలోచనలు ఉత్పన్నమైతే, వాటిని పూర్తిచేయడానికి ప్రయత్నించకుండా, ఈ ఆలోచన ఎవరికో వచ్చిందో తెలుసుకోవాలి. ఎంతమంది ఆలోచనలు ఉత్పన్నమవుతున్నాయనే విషయం ఏమిటి? ప్రతి ఆలోచన ఉత్పన్నమైతే, మనం జాగ్రత్తగా ఉండాలి మరియు ఈ ఆలోచన ఎవరికో జరుగుతోందో అడగాలి. సమాధానం ‘నాకు’ అని ఉంటుంది. మీరు ‘నేను ఎవరు?’ అని అడిగితే, మనస్సు దాని మూలానికి (లేదా అది ఎక్కడి నుండి వచ్చిందో) తిరిగి వస్తుంది. ఉత్పన్నమైన ఆలోచన కూడా మునిగిపోతుంది. మీరు ఇలాగే మరింతగా సాధన చేస్తే, మీ మనస్సు దాని మూలంగా ఉండే శక్తి పెరుగుతుంది.\n\nసమర్పణ\n\nసమర్పణను సాధించడానికి రెండు మార్గాలు ఉన్నాయి. ఒకటి ‘నేను’ యొక్క మూలాన్ని పరిశీలించడం మరియు ఆ మూలంలో విలీనమవడం. ఇతరుడు \'నేను అశక్తుడిని, దేవుడు మాత్రమే శక్తివంతుడు మరియు నా కోసం పూర్తిగా ఆయనపై విరమించడం తప్ప మరొక రక్షణ మార్గం లేదు\' అని భావిస్తున్నాడు, మరియు ఈ విధంగా దేవుడు మాత్రమే ఉన్నాడు మరియు అహంకారం లెక్కలోకి రాదు అనే నమ్మకాన్ని క్రమంగా అభివృద్ధి చేస్తాడు. ఈ రెండు పద్ధతులు ఒకే లక్ష్యానికి చేరుకుంటాయి. పూర్తిగా సమర్పణ అనేది జ్ఞాన లేదా ముక్తి యొక్క మరో పేరు.\n\nమూడు స్థితులు: మేల్కొనడం, కల, మరియు నిద్ర\n\nకల మరియు మేల్కొనడం స్థితుల మధ్య వ్యత్యాసం లేదు, కల చిన్నది మరియు మేల్కొనడం పొడవుగా ఉంటుంది. రెండూ మనసు యొక్క ఫలితాలు. మన నిజమైన స్థితి మేల్కొనడం, కల మరియు నిద్ర స్థితుల కంటే మించి ఉంది, దీనిని తురీయ అంటారు.\n\nశ్రీ రామణ మహర్షి కృప మరియు గురు\n\nనేను గురువు అవసరం లేదని చెప్పలేదు. కానీ గురువు ఎప్పుడూ మానవ రూపంలో ఉండాలి అనేది అవసరం లేదు. మొదట ఒక వ్యక్తి తాను తక్కువ స్థాయి వ్యక్తి అని, తనకు మరియు ప్రపంచానికి విధిని నియంత్రించే ఒక ఉన్నత, సమస్తజ్ఞుడు, సమస్తశక్తిమంతుడు అయిన దేవుడు ఉన్నాడని ఆలోచిస్తాడు మరియు అతనిని పూజిస్తాడు లేదా భక్తి చేస్తాడు. ఒక నిర్దిష్ట స్థాయికి చేరుకున్నప్పుడు, అతను ప్రకాశం పొందడానికి అర్హుడవుతాడు, అతను పూజించిన అదే దేవుడు గురువుగా వస్తాడు మరియు అతన్ని మార్గనిర్దేశం చేస్తాడు. ఆ గురువు అతనికి ‘ఆ దేవుడు నీలోనే ఉన్నాడు. లోతుగా వెళ్లి తెలుసుకో’ అని చెప్పడానికి మాత్రమే వస్తాడు. దేవుడు, గురువు మరియు ఆత్మ ఒకటే.\n\nఆత్మ-అవగాహన\n\nమనం అవగాహన అని పిలిచే స్థితి అనేది కేవలం స్వయంగా ఉండటం, ఏమీ తెలియకపోవడం లేదా ఏదైనా కావడం కాదు. ఒకరు అవగాహన పొందితే, అతను కేవలం ఉన్నది, ఎప్పుడూ ఉన్నది. అతను ఆ స్థితిని వివరిస్తాడు. అతను కేవలం ఆది కావాలి. ఖచ్చితంగా, మేము మెరుగైన పదం లేకపోవడంతో ఆత్మ-అవగాహన గురించి సడలించి మాట్లాడుతాము.\n\n‘ఉన్నది’ శాంతి. మనం చేయాల్సింది కేవలం నిశ్శబ్దంగా ఉండటం. శాంతి మన నిజమైన స్వభావం. మనం దానిని దెబ్బతీస్తున్నాము. దానిని దెబ్బతీయడం ఆపాలని అవసరం ఉంది.\n\nహృదయం\n\nహృదయపు గహనంలో, ఒక్కడే బ్రహ్మన్ \'నేను\'-\'నేను\' అనుభూతిలో ఆత్మగా (ఆత్మ) తనలో తానే ప్రకాశిస్తుంది. మీలోని ఆత్మను అన్వేషించడానికి శ్వాసను నియంత్రించడం లేదా ఆలోచనను కేంద్రీకరించడం ద్వారా హృదయాన్ని చేరుకోండి. అప్పుడు మీరు ఆత్మలో స్థిరపడతారు.\n\nత్యాగం\n\n‘మోక్షం (ముక్తి) యొక్క పథంలో ఒక గృహస్థుడు ఎలా ఉంటాడు?’ అని అడిగినప్పుడు, భగవాన్ చెప్పారు, ‘మీరు గృహస్థుడిగా ఎందుకు భావిస్తున్నారు? మీరు సన్యాసిగా (తపస్వి) బయటకు వెళ్ళితే, మీరు సన్యాసిగా ఉన్నారని ఆలోచన మీను వెంటాడుతుంది. మీరు గృహంలో కొనసాగుతారా లేదా దానిని విడిచి అడవిలో వెళ్ళుతారా, మీ మనసు మీతో ఉంటుంది. అహంకారం అన్ని ఆలోచనల మూలం. ఇది శరీరాన్ని మరియు ప్రపంచాన్ని సృష్టిస్తుంది మరియు మీరు ఒక గృహస్థ అని భావింపజేస్తుంది. మీరు ప్రపంచాన్ని వదిలిస్తే, అది గృహస్థకు బదులు సన్యాసి ఆలోచనను మాత్రమే అందిస్తుంది మరియు అటవీ పరిసరాలను గృహ పరిసరాలతో మారుస్తుంది. కానీ మానసిక అడ్డంకులు ఇంకా అక్కడే ఉంటాయి. కొత్త పరిసరాల్లో అవి మరింత పెరుగుతాయి. పరిసరాల మార్పులో సహాయం లేదు. అడ్డంకి మనసు. ఇది ఇంట్లో లేదా అటవీ లో ఉండి అధిగమించాలి. మీరు అటవీ లో చేయగలిగితే, ఇంట్లో ఎందుకు కాదు? కాబట్టి, మీ పరిసరాలను ఎందుకు మార్చాలి? మీరు ప్రస్తుతం ఉన్న పరిసరాల్లో కూడా మీ ప్రయత్నాలను చేయవచ్చు. మీ కోరిక ప్రకారం పరిసరాలు ఎప్పుడూ మారవు.\n\nనియతి మరియు స్వేచ్ఛా సంకల్పం\n\nస్వేచ్ఛా సంకల్పం మరియు నియతి ఎప్పుడూ ఉనికిలో ఉంటాయి. భవిష్యత్తు గత క్రియల ఫలితమే; ఇది శరీరాన్ని సంబంధించింది. శరీరం ఎలా కావాలో అలా పనిచేయనివ్వండి. దానిపై మీరు ఎందుకు ఆందోళన చెందుతున్నారు? దానిపై మీరు ఎందుకు దృష్టి పెట్టుతున్నారు? స్వేచ్ఛా ఇచ్ఛ మరియు భవిష్యత్తు శరీరం ఉన్నంత కాలం ఉంటాయి. కానీ జ్ఞానం రెండు దాటిస్తుంది. ఆత్మ జ్ఞానం మరియు అజ్ఞానం మించిపోయింది. ఏమి జరుగుతుందో, అది వ్యక్తి గత క్రియల ఫలితంగా, దివ్య ఇచ్ఛ మరియు ఇతర అంశాల ఫలితంగా జరుగుతుంది.\n\nభవిష్యత్తును అధిగమించడానికి లేదా దాని నుండి స్వతంత్రంగా ఉండడానికి రెండు మార్గాలు మాత్రమే ఉన్నాయి. ఒకరు ఈ విధిని కోసం ఎవరు అని ప్రశ్నించాలి మరియు ఈ విధి ద్వారా కేవలం అహంకారం మాత్రమే బంధించబడిందని, ఆత్మ మాత్రం బంధించబడలేదని తెలుసుకోవాలి మరియు అహంకారం అనేది不存在. \n\nమరొక మార్గం అహంకారాన్ని చంపడం, అంటే పరమేశ్వరునికి పూర్తిగా సమర్పణ చేయడం, తన అసహాయతను గ్రహించడం మరియు ఎప్పుడూ ‘నేను కాదు, నీవు ఓ పరమేశ్వర’ అని చెప్పడం, ‘నేను’ మరియు ‘నా’ అన్న భావనను వదులుకోవడం, మరియు పరమేశ్వరునికి మీతో ఏమి చేయాలో వదిలించడం. అహంకారాన్ని పూర్తిగా తొలగించడం విధిని అధిగమించడానికి అవసరం, మీరు ఈ తొలగింపును ఆత్మ-ప్రశ్న ద్వారా లేదా భక్తి మార్గం ద్వారా సాధించినా సరే.\n\nజ్ఞాని\n\nఒక జ్ఞాని జీవించేటప్పుడు కూడా విముక్తిని పొందాడు, ఇక్కడ మరియు ఇప్పుడు. అతనికి శరీరాన్ని ఎలా, ఎక్కడ, ఎప్పుడు వదులుతాడనేది ప్రాధాన్యం లేదు. కొన్ని జ్ఞానులు బాధపడుతున్నట్లు కనిపించవచ్చు, మరికొంత మంది సమాధిలో ఉండవచ్చు; మరికొంత మంది మరణానికి ముందు కంటికి కనబడకుండా పోవచ్చు. కానీ ఇది వారి జ్ఞానానికి ఎలాంటి తేడా కలిగించదు. ఇలాంటి బాధలు ప్రాథమికంగా కనిపిస్తాయి, చూసేవారికి నిజంగా అనిపించవచ్చు, కానీ జ్ఞానికి అనుభవం ఉండదు, ఎందుకంటే అతను శరీరంతో ఆత్మ యొక్క తప్పు గుర్తింపును మించిపోయాడు.\n\nజ్ఞాని తనను శరీరం అని భావించడు. అతను శరీరాన్ని కూడా చూడడు. అతను శరీరంలో కేవలం ఆత్మను మాత్రమే చూస్తాడు. శరీరం లేకపోతే, కేవలం ఆత్మ మాత్రమే ఉంటే, దాని ఏ రూపంలో కనుమరుగవ్వడం అనే ప్రశ్న ఉత్పన్నం కాదు.\n\nశ్రీ రామణ మహర్షి తో కుందలు సాధన, అంకితభావం మరియు భక్తి\n\nశ్రీ రామణ మహర్షి యొక్క జీవితం మరియు ఉపదేశాల వెలుగులో, అరుణాచల ఆశ్రమం భక్తులు ఆధ్యాత్మిక సాధన (సాధన) అనివార్యమని నమ్ముతారు. శాంతి, ఆనందం మరియు అమరత్వం ధ్యానం, ఆత్మ పరిశీలన మరియు భక్తి సాధనలో తమను అంకితం చేసే ఆవేదనలకోసం అందుబాటులో ఉన్నాయి. గురువు యొక్క కృప ఎప్పుడూ ఉనికిలో ఉంది, కానీ ఈ కృపను పూర్తిగా అనుభవించడం కేవలం తమ జీవితాలను ఉపదేశాల సాధనకు అంకితం చేసిన కొద్దిమంది నిజమైన సాధకుల ద్వారా మాత్రమే జరుగుతుంది.\n\nశ్రీ రామణ మహర్షి తన కాలానికి మాత్రమే జీవించలేదు అని మేము నమ్ముతాము. ఆయన శరీరంగా ఉన్నప్పుడు అనుభవించినట్లుగా, ఆయన ఉనికిని మరియు మార్గదర్శకత్వాన్ని ఇప్పుడు కూడా అనుభవించవచ్చు. ఆయన వైపు నిజమైన ఆవేదన మరియు ఆకాంక్షతో తిరుగుతున్న వారు, ఆయన ఉపదేశాలను అన్వయించడానికి తమ ఉత్తమాన్ని ప్రయత్నించే వారు, ఆయన కృప మరియు మార్గదర్శకత్వాన్ని అనుభవిస్తారు. దీనిపై ఎలాంటి సందేహం లేదు.\n\nఅరుణాచల ఆశ్రమంలో, భగవాన్ శ్రీ రామణ మహర్షి ఉపాధ్యాయుడు మరియు గురువు గా ఉన్నారు. ప్రవచనాలు మరియు చర్చలు ఒక ఆశావహుడి జీవితంలో స్థానం కలిగి ఉండవచ్చు, కానీ అరుణాచల ఆశ్రమం సందర్శకులు మరియు నివాసితులు శ్రీ రామణ మహర్షి యొక్క ఉపదేశాలను నిశ్శబ్దం ద్వారా గ్రహించగలిగే విధంగా నిర్వహించబడింది. ఆయన ఉపదేశాలు ఎప్పుడూ నిశ్శబ్దంలో వ్యాప్తి చెందుతున్నాయి, మరియు వాటిని వినాలంటే మన మానసిక శాంతిని సాధించాలి. ప్రవచనాలు మరియు చర్చలు ఆయన నిశ్శబ్ద ఉపదేశాన్ని మన హృదయంలో మసకబార్చవచ్చు.\n\n“నిశ్శబ్దం అన్ని ధర్మాల నదులు ప్రవహించే సముద్రం.” \n\n— తాయుమానవర్\n\nగురు\n\nశ్రీ మహర్షి ఒక గురువు అవసరమని చెప్పారు. ఆయన చెప్పినట్లుగా, గురువు బాహ్యంగా ఉండకపోవచ్చు. మరలా, ఆయన శారీరక మరణం తర్వాత, ఆయన శరీరంతో ఎప్పుడూ గుర్తించబడలేదని చెప్పారు; అంటే, ఆయన ఇప్పటికీ ఉన్నారు. \n\nసత్యం ఏమిటంటే, ఎవరూ మనకు ముక్తిని ఇవ్వలేరు. మార్గం చూపించబడవచ్చు, దిశలు ఇవ్వబడవచ్చు. మన ఉత్కంఠ మరియు లక్ష్యానికి పూర్తి అంకితభావం అత్యంత ముఖ్యమైన అంశం. మనం ఈ ఒక్క విషయంపై – సత్యాన్ని గ్రహించడం – మక్కువతో ఉంటే, సత్యం, అవసరమైతే శారీరక గురువు మరియు మిగతా అన్ని విషయాలు స్వయంగా మన వైపు ఆకర్షించబడతాయి. మనం సిద్ధంగా ఉన్నప్పుడు గురువు మనకు వస్తారు. మనం మనలను సిద్ధం చేసుకోవడంపై దృష్టి పెట్టాలి, మిగతా విషయాలు స్వయంగా జరుగుతాయి. మహర్షి యొక్క జీవిత ఉనికిపై విశ్వాసం ఉన్న వారికి ఈ విషయంపై ఎలాంటి సందేహాలు ఉండవు.'
    ),
    Article(
        heading: 'నేను ఎవరు - మహర్షి రామణ యొక్క ఏకైక పుస్తకం',
        body: 'ఓం నమో భగవతే శ్రీ రామనాయ\n\nనేను ఎవరు?\n\n(నాన్ యార్?)\n\nప్రతి జీవి ఎల్లప్పుడూ సంతోషంగా ఉండాలని, బాధ లేకుండా ఉండాలని కోరుకుంటుంది. ప్రతి ఒక్కరికి తనకు ఉన్న అత్యున్నత ప్రేమను గమనించవచ్చు. సంతోషమే ప్రేమకు కారణం, అందువల్ల మన స్వభావం అయిన, మేధస్సు లేని లోతైన నిద్రలో అనుభవించే ఆ సంతోషాన్ని పొందడానికి, మనను తెలుసుకోవాలి. అందుకు, జ్ఞాన మార్గం, "నేను ఎవరు?" అనే ప్రశ్నను విచారించడం ప్రధాన మార్గం.\n\n1. నేను ఎవరు?\n\nఏడు ద్రవాలు (ధాతులు) కలిగిన క粗 శరీరమే నేను కాదు; ఐదు జ్ఞానేంద్రియాలు, అంటే వినడం, స్పృశించడం, చూడడం, రుచి చూడడం, మరియు వాసన తెలుసుకోవడం, ఇవి తమ సంబంధిత వస్తువులను గ్రహిస్తాయి. శబ్దం, స్పర్శ, రంగు, రుచి, మరియు వాసన, నేను కాదు; ఐదు జ్ఞానేంద్రియాలు, అంటే మాట, కదలిక, పట్టుకోవడం, మలమూత్రం, మరియు సృష్టి, వీటి కార్యాలు మాట్లాడడం, కదలడం, పట్టుకోవడం, మలమూత్రం చేయడం, మరియు ఆనందించడం, నేను కాదు; ఐదు ప్రాణవాయువులు, ప్రాణం మొదలైనవి, ఇవి అనుక్రమంగా ఐదు కార్యాలను నిర్వహిస్తాయి, నేను కాదు; ఆలోచించే మనస్సు కూడా, నేను కాదు; వస్తువుల మిగిలిన ముద్రలతో మాత్రమే ఉన్న అజ్ఞానం, అందులో వస్తువులు మరియు కార్యాలు లేవు, నేను కాదు.  \n  \n2. నేను ఇవన్నీ కాదు, అయితే నేను ఎవరు?  \n  \nఈ ‘ఇది కాదు’, ‘ఇది కాదు’ అని అన్న తర్వాత, మాత్రమే మిగిలిన ఆ అవగాహన - అది నేను. అవగాహన యొక్క స్వభావం ఏమిటి? \n\nఅవగాహన యొక్క స్వభావం ఉనికిఅవగాహన-ఆనందం \n\n4. ఆత్మ యొక్క అనుభవం ఎప్పుడు పొందబడుతుంది? \n\nచూడబడుతున్న ప్రపంచం తొలగించినప్పుడు, చూడువాడు అయిన ఆత్మ యొక్క అనుభవం పొందబడుతుంది. \n\n5. ప్రపంచం ఉన్నప్పుడు (అది వాస్తవంగా తీసుకుంటే) ఆత్మ యొక్క అనుభవం ఉండదు కదా? \n\nఉండదు. \n\n6. ఎందుకు? \n\nచూడువాడు మరియు చూడబడుతున్న వస్తువు రశ్మి మరియు పాము వంటి ఉన్నాయి. మాయా పాముకు సంబంధించిన తప్పు అవగాహన పోకుండా, మౌలికమైన రశ్మి యొక్క అవగాహన కలుగదు, అలాగే ప్రపంచం వాస్తవంగా ఉందని నమ్మకం తొలగించబడకుండా, మౌలికమైన ఆత్మ యొక్క అనుభవం పొందబడదు. \n\n7. ప్రపంచం, ఇది చూడబడే వస్తువు, ఎప్పుడు తొలగించబడుతుంది? \n\nఅన్ని జ్ఞానాలు మరియు అన్ని చర్యల కారణమైన మనస్సు శాంతించగానే, ప్రపంచం అదృశ్యమవుతుంది. \n\n8. మనస్సు యొక్క స్వభావం ఏమిటి? \n\n‘మనస్సు’ అని పిలవబడేది ఆత్మలో నివసించే అద్భుతమైన శక్తి. ఇది అన్ని ఆలోచనలు ఉత్పత్తి చేస్తుంది. \n\nఆలోచనల తప్ప, మనస్సు అనే దానికి ఎలాంటి స్వతంత్ర సত্তా లేదు. అందువల్ల, ఆలోచన మనస్సు యొక్క స్వభావం. ఆలోచనల తప్ప, ప్రపంచం అనే స్వతంత్ర సత్తా లేదు. లోతైన నిద్రలో ఆలోచనలు ఉండవు, మరియు ప్రపంచం ఉండదు. మేల్కొనడం మరియు కలల స్థితుల్లో, ఆలోచనలు ఉంటాయి, మరియు ప్రపంచం కూడా ఉంటుంది. జాలకోడి తనలోనుంచి తంతు (జాలం)ను వెలువరించి, మళ్లీ దానిని తనలోకి తీసుకువస్తుంది; అలాగే మనస్సు కూడా తనలోనుంచి ప్రపంచాన్ని వెలువరించి, మళ్లీ దానిని తనలోకి సమీకరిస్తుంది. మనస్సు ఆత్మ నుండి బయటకు వచ్చినప్పుడు, ప్రపంచం కనిపిస్తుంది. అందువల్ల, ప్రపంచం కనిపించినప్పుడు (వాస్తవంగా) ఆత్మ కనిపించదు; మరియు ఆత్మ కనిపించినప్పుడు (ప్రకాశిస్తుంది) ప్రపంచం కనిపించదు. ఒకరు నిరంతరం మనస్సు స్వభావాన్ని పరిశీలిస్తే, మనస్సు ముగుస్తుంది, ఆత్మ (మిగిలినది)గా ఉంటుంది. ఆత్మగా సూచించబడేది అట్మన్. మనస్సు ఎప్పుడూ ఏదో దృఢమైన దానిపై ఆధారపడి మాత్రమే ఉంటుంది; అది ఒంటరిగా ఉండలదు. మనస్సు సున్నిత శరీరం లేదా ఆత్మ (జీవ) అని పిలువబడుతుంది. మనస్సు యొక్క స్వభావాన్ని అర్థం చేసుకోవడానికి ప్రశ్నించు మార్గం ఏమిటి? \n\nఈ శరీరంలో ‘నేను’గా ఉద్భవించేది మనస్సు. ‘నేను’ అనే ఆలోచన శరీరంలో ఎక్కడ మొదట ఉద్భవిస్తుందో ప్రశ్నిస్తే, అది హృదయంలో ఉద్భవిస్తుందని కనుగొంటారు. అదే మనస్సు యొక్క ఉద్భవ స్థలం. ఎవరు నిరంతరం ‘నేను’ ‘నేను’ అని ఆలోచించినా, వారు ఆ స్థలానికి చేరుకుంటారు. మనస్సులో ఉద్భవించే ఆలోచనలలో, ‘నేను’ ఆలోచన మొదటిది. దీని ఉద్భవం తర్వాత ఇతర ఆలోచనలు ఉద్భవిస్తాయి. మొదటి వ్యక్తి సర్వనామం కనిపించిన తర్వాత, రెండవ మరియు మూడవ వ్యక్తి సర్వనామాలు కనిపిస్తాయి; మొదటి వ్యక్తి సర్వనామం లేకుండా, రెండవ మరియు మూడవ వ్యక్తి ఉండవు. \n\n10. మనస్సు ఎలా శాంతించగలదు? \n\n‘నేను ఎవరు?’ అనే ప్రశ్న ద్వారా. ‘నేను ఎవరు?’ అనే ఆలోచన అన్ని ఇతర ఆలోచనలను నాశనం చేస్తుంది, మరియు దహన సమాధి కదిలించడానికి ఉపయోగించే కర్ర లాంటిది, అది చివరికి నాశనం అవుతుంది. అప్పుడు, ఆత్మ-సాక్షాత్కారం ఉత్పన్నమవుతుంది.\n\n11. ‘నేను ఎవరు?’ అనే ఆలోచనను నిరంతరం పట్టుకోవడానికి మార్గం ఏమిటి?\n\nఇతర ఆలోచనలు ఉత్పన్నం అయితే, వాటిని అనుసరించకూడదు, కానీ ‘వాటికి ఎవరు ఉత్పన్నమవుతున్నారు?’ అని విచారించాలి. ఎంతమాత్రం ఆలోచనలు ఉత్పన్నమవుతాయో అది ముఖ్యం కాదు. ప్రతి ఆలోచన ఉత్పన్నమవుతున్నప్పుడు, ఒకరు శ్రద్ధగా విచారించాలి, “ఈ ఆలోచన ఎవరికో ఉత్పన్నమైంది?”. వచ్చే సమాధానం “నాకు” అవుతుంది. అప్పుడు ఒకరు “నేను ఎవరు?” అని విచారిస్తే, మనస్సు దాని మూలానికి తిరిగి వెళ్ళుతుంది; మరియు ఉత్పన్నమైన ఆలోచన శాంతించుతుంది. ఈ విధంగా పునరావృత సాధనతో, మనస్సు దాని మూలంలో ఉండటానికి నైపుణ్యం అభివృద్ధి చేస్తుంది. సూక్ష్మమైన మనస్సు మస్తిష్కం మరియు ఇంద్రియాల ద్వారా బయటకు వెళ్ళినప్పుడు, ఘనమైన పేర్లు మరియు రూపాలు కనిపిస్తాయి; అది హృదయంలో ఉండగా, పేర్లు మరియు రూపాలు అదృశ్యమవుతాయి. మనస్సును బయటకు వెళ్ళనివ్వకుండా, హృదయంలో ఉంచడం “అంతర్ముఖత” (antarmukha) అని పిలువబడుతుంది. హృదయాన్ని దాటించి మనస్సును బయటకు వెళ్ళనివ్వడం “బాహ్యముఖత” (bahir-mukha) అని పిలువబడుతుంది. అలా, మనస్సు హృదయంలో ఉండగా, అన్ని ఆలోచనల మూలమైన ‘నేను’ పోతుంది, ఎప్పుడూ ఉన్న ఆత్మ ప్రకాశిస్తుంది. మనిషి ఏది చేసినా, ‘నేను’ అనే అహంకారాన్ని లేకుండా చేయాలి. అలా చేస్తే, అన్నీ శివ (దేవుడు) స్వభావంగా కనిపిస్తాయి.  \n12. మనస్సును శాంతంగా చేయడానికి ఇతర మార్గాలు లేవా?  \nఅన్వేషణను మినహాయించి, సరిపడా మార్గాలు లేవు. మరే విధానాల ద్వారా మనసును నియంత్రించడానికి ప్రయత్నిస్తే, మనసు నియంత్రించబడినట్లుగా కనిపిస్తుంది, కానీ అది మళ్లీ కదలడం ప్రారంభిస్తుంది. శ్వాసను నియంత్రించడం ద్వారా కూడా, మనసు శాంతంగా ఉంటుంది; కానీ శ్వాస నియంత్రించబడినంత కాలం మాత్రమే అది శాంతంగా ఉంటుంది, మరియు శ్వాస తిరిగి ప్రారంభించగానే మనసు మళ్లీ కదలడం ప్రారంభించి, మిగిలిన ముద్రల ద్వారా ప్రేరేపితంగా తిరుగుతుంది. మనసు మరియు శ్వాస రెండింటికీ మూలం ఒకే. ఆలోచన, నిజంగా, మనసు యొక్క స్వభావం. "నేను" అనే ఆలోచన మనసు యొక్క మొదటి ఆలోచన; మరియు అది అహంకారాన్ని సూచిస్తుంది. అహంకారం ఉద్భవించే స్థలం నుండి శ్వాస కూడా ఉద్భవిస్తుంది. అందువల్ల, మనసు శాంతంగా ఉన్నప్పుడు, శ్వాస నియంత్రించబడుతుంది, మరియు శ్వాస నియంత్రించబడినప్పుడు మనసు శాంతంగా ఉంటుంది. కానీ లోతైన నిద్రలో, మనసు శాంతించ although, శ్వాస ఆగదు. ఇది దేవుని ఇష్టానికి కారణం, శరీరం కాపాడబడాలని మరియు ఇతరులు అది మృతంగా ఉన్నట్లు భావించకూడా. మేల్కొనడం మరియు సమాధి స్థితిలో, మనసు శాంతించ when, శ్వాస నియంత్రించబడుతుంది. \n\nశ్వాస అనేది మనసు యొక్క దృశ్య రూపం. మరణ సమయానికి, మనసు శ్వాసను శరీరంలో ఉంచుతుంది; మరియు శరీరం మరిచి పోతే, మనసు శ్వాసను తనతో తీసుకెళ్తుంది. అందువల్ల, శ్వాస నియంత్రణ అనేది కేవలం మనసును శాంతించ (మనోనిగ్రహ) చేయడానికి సహాయమే; ఇది మనసును నాశనం చేయదు (మనోనాస). శ్వాస నియంత్రణ సాధన, దేవుని రూపాలపై ధ్యానం, మంత్రాల పునరావృతం, ఆహారంపై పరిమితి మొదలైనవి, మనసును శాంతించ (మనోనిగ్రహ) చేయడానికి సహాయాలు మాత్రమే. దేవుని రూపాలను ధ్యానించడం మరియు మంత్రాలను పునరావృతం చేయడం ద్వారా, మనస్సు ఒకే దిశలో కేంద్రీకృతమవుతుంది. మనస్సు ఎప్పుడూ తిరుగుతూ ఉంటుంది. ఒక ఏనుగుకు దాని గడ్డలో పట్టుకునేందుకు ఒక గొలుసు ఇచ్చినప్పుడు, అది ఆ గొలుసును పట్టుకొని మాత్రమే ముందుకు వెళ్ళుతుంది, అలాగే ఒక పేరు లేదా రూపంతో మనస్సు నిమగ్నమైతే, అది ఆ ఒక్కటిని మాత్రమే పట్టుకుంటుంది. మనస్సు అనేక ఆలోచనల రూపంలో విస్తరించినప్పుడు, ప్రతి ఆలోచన బలహీనమవుతుంది; కానీ ఆ ఆలోచనలు పరిష్కరించబడినప్పుడు, మనస్సు కేంద్రీకృతమై బలవంతంగా మారుతుంది; అటువంటి మనస్సుకు ఆత్మ పరిశీలన సులభంగా అవుతుంది. అన్ని నియమాలలో, సాత్విక ఆహారాన్ని పరిమిత పరిమాణంలో తీసుకోవడం సంబంధిత నియమం ఉత్తమం; ఈ నియమాన్ని పాటించడం ద్వారా, మనస్సు సాత్విక గుణం పెరుగుతుంది, మరియు అది ఆత్మ పరిశీలనకు సహాయపడుతుంది. 13. వస్తువుల మిగిలిన ముద్రలు (చింతనలు) సముద్రపు తరంగాల్లా వంచన చేస్తున్నాయి. అవి ఎప్పుడు నాశనం అవుతాయి? ఆత్మపై ధ్యానం ఎప్పటికీ పెరుగుతున్నప్పుడు, ఆ చింతనలు నాశనం అవుతాయి. 14. ప్రారంభరహిత కాలం నుండి వచ్చిన వస్తువుల మిగిలిన ముద్రలు పరిష్కరించబడటం, మరియు ఒకరు శుద్ధ ఆత్మగా ఉండటం సాధ్యమా? "సాధ్యమా, లేదా కాదు?" అనే సందేహానికి తలవంచకుండా, ఆత్మపై ధ్యానాన్ని పట్టుకొని ఉండాలి. ఒకరు గొప్ప పాపి అయినా, "ఓ! నేను పాపి, నేను ఎలా రక్షించబడుతాను?" అని ఆందోళన చెందకూడదు; "నేను పాపి" అనే ఆలోచనను పూర్తిగా వదులుకోవాలి; మరియు ఆత్మపై ధ్యానంలో కేంద్రీకృతమవ్వాలి; అప్పుడు, ఒకరు తప్పకుండా విజయం సాధిస్తారు. రెండు మనసులు లేవు - ఒకటి మంచి మరియు మరొకటి చెడు; మనసు ఒకటే. ఇది రెండు రకాల మిగిలిన ముద్రలు - శుభ మరియు అశుభ. మనసు శుభ ముద్రల ప్రభావంలో ఉన్నప్పుడు అది మంచి అని అంటారు; మరియు అశుభ ముద్రల ప్రభావంలో ఉన్నప్పుడు అది చెడు అని భావిస్తారు. మనసు భౌతిక వస్తువుల వైపు మరియు ఇతరుల విషయాల వైపు తిరగకుండా ఉండాలి. ఇతరులు ఎంత చెడ్డవాళ్ళైనా, వారికి ద్వేషం కలిగించకూడదు. ఇష్టాలు మరియు ద్వేషం రెండూ వదలాలి. ఇతరులకు ఇచ్చే ప్రతీది, మనకు ఇచ్చే ప్రతీది. ఈ సత్యం అర్థం చేసుకుంటే, ఎవరు ఇతరులకు ఇవ్వరు? మన స్వరూపం ఉద్భవించినప్పుడు, అన్నీ ఉద్భవిస్తాయి; మన స్వరూపం నిశ్శబ్దంగా ఉన్నప్పుడు, అన్నీ నిశ్శబ్దంగా ఉంటాయి. మనం వినయంతో ప్రవర్తించినంత కాలం, అంత కాలం మంచితనం ఫలితంగా వస్తుంది. మనసు శాంతంగా ఉంటే, ఎక్కడైనా జీవించవచ్చు. 15. విచారణ ఎంతకాలం ప్రాక్టీస్ చేయాలి? \n\nమనసులో వస్తువుల ముద్రలు ఉన్నంత కాలం, "నేను ఎవరు?" అనే విచారణ అవసరం. ఆలోచనలు ఉద్భవించినప్పుడు, వాటి ఉద్భవ స్థలంలోనే వాటిని విచారణ ద్వారా నాశనం చేయాలి. ఎవరు నిరంతరం ఆత్మను ధ్యానిస్తే, ఆత్మ పొందే వరకు, అది మాత్రమే సరిపోతుంది. కోటలో శత్రువులు ఉన్నంత కాలం, వారు బయటకు వస్తూనే ఉంటారు; వారు బయటకు వచ్చినప్పుడు నాశనం చేస్తే, కోట మన చేతుల్లో పడుతుంది. \n\n16. ఆత్మ యొక్క స్వభావం ఏమిటి? \n\nనిజంగా ఉన్నది కేవలం ఆత్మ మాత్రమే. ప్రపంచం, వ్యక్తిగత ఆత్మ మరియు దేవుడు ఇవన్నీ అందులోని రూపాలు. ముత్యాలలో వెండి వంటి ఈ మూడు ఒకేసారి కనిపిస్తాయి మరియు ఒకేసారి అదృశ్యమవుతాయి. "నేను" భావన ఉండని స్థానం ఆత్మ. దాన్ని "నిశ్శబ్దం" అంటారు. ఆత్మే ప్రపంచం; ఆత్మే "నేను"; ఆత్మే దేవుడు; అన్నీ శివమే, ఆత్మ. 17. అన్నీ దేవుని పనిగా ఉండదా? \n\nకామన, సంకల్పం లేదా ప్రయత్నం లేకుండా, సూర్యుడు ఉదయిస్తాడు; మరియు తన కేవలం ఉనికిలో, సూర్యరత్నం అగ్ని విడుదల చేస్తుంది, కమలము పూస్తుంది, నీరు ఆవిరైపోతుంది; ప్రజలు తమ వివిధ పనులను నిర్వహిస్తారు మరియు తరువాత విశ్రాంతి తీసుకుంటారు. మాగ్నెట్ సమీపంలో నడికాయ ఎలా కదులుతుందో, అదే విధంగా మూడు (సామాన్య) కార్యాల లేదా ఐదు దివ్య కార్యకలాపాల ద్వారా పాలనలో ఉన్న ఆత్మలు తమ కర్మల ప్రకారం తమ చర్యలను నిర్వహించి, అనంతరం విశ్రాంతి పొందుతాయి. దేవుడు ఎలాంటి సంకల్పం కలిగి ఉండడు; ఆయనకు ఎలాంటి కర్మలు అంటిపెట్టుకోవు. ఇది సూర్యుడిపై భౌతిక చర్యలు ప్రభావం చూపకపోవడం లేదా నాలుగు మూలకాల సుకృతాలు మరియు దోషాలు అంతా వ్యాపించిన స్థలాన్ని ప్రభావితం చేయకపోవడం వంటి విషయమే. \n\nభక్తులలో, ఎవరు అత్యుత్తముడు? \n\nదేవుడైన ఆత్మకు తనను అర్పించేవాడు అత్యుత్తమ భక్తుడు. దేవునికి తనను అర్పించడం అంటే ఆత్మలో నిరంతరం ఉండడం, ఆత్మకు మినహాయించి ఏ ఆలోచనలకు స్థలం ఇవ్వకుండా ఉండడం. దేవుడిపై వేయబడిన ఏ భారం ఉన్నా, ఆయన దాన్ని భరించుకుంటాడు. దైవం యొక్క పరమ శక్తి అన్ని విషయాలను కదిలిస్తుంది కాబట్టి, దానికి సమర్పించుకోకుండా, మనం ఏం చేయాలి, ఎలా చేయాలి, ఏం చేయకూడదు మరియు ఎలా చేయకూడదు అనే ఆలోచనలతో నిరంతరం ఆందోళన చెందడం ఎందుకు? రైలు అన్ని లోడ్లను తీసుకువెళ్ళడం మనకు తెలుసు కాబట్టి, దానిపై ఎక్కిన తర్వాత, మన చిన్న బరువును తలపై పెట్టుకుని అసౌకర్యంగా ఉండడం ఎందుకు? దానిని రైలులో ఉంచి సుఖంగా ఉండడం మంచిది కదా?\n\n19. అనాసక్తి అంటే ఏమిటి?\n\nఆలోచనలు ఉద్భవించినప్పుడు, వాటిని పూర్తిగా నాశనం చేయడం, అవి ఉద్భవించిన ప్రదేశంలోనే, అనాసక్తి. ముత్యాల కోసం నీటిలోకి దిగే ముత్యాల దొర కట్టుకున్న రాళ్లను తన కండరానికి కట్టుకుని, సముద్రపు తలుపు కిందకి దిగినట్లు, మనలో ప్రతి ఒక్కరూ అనాసక్తితో నిండి, అంతరంగంలోకి దిగాలి మరియు ఆత్మ-ముత్యం పొందాలి. దేవుడు మరియు గురువు ఒక ఆత్మను విముక్తి పొందించడానికి సహాయపడడం సాధ్యం కాదా? \n\nదేవుడు మరియు గురువు విముక్తి మార్గాన్ని మాత్రమే చూపిస్తారు; వారు ఆత్మను విముక్తి స్థితికి తీసుకెళ్లరు. నిజానికి, దేవుడు మరియు గురువు వేరువేరుగా ఉండరు. పులి దంతాల్లో పడిన పశువు తప్పించుకోలేకపోతుంది, అలాగే గురువుని దయగల దృష్టిలో వచ్చిన వారు గురువుతో రక్షించబడతారు మరియు తప్పిపోరు; అయితే, ప్రతి ఒక్కరు తమ స్వంత ప్రయత్నంతో దేవుడు లేదా గురువు చూపించిన మార్గాన్ని అనుసరించి విముక్తిని పొందాలి. ఒకరు తనను తాను తెలుసుకోవడానికి తన స్వంత జ్ఞాన కంటితో మాత్రమే తెలుసుకోవచ్చు, ఇతరుల కంటితో కాదు. రాముడు తనను రాముడుగా తెలుసుకోవడానికి అద్దం సహాయం అవసరమా? మోక్షాన్ని కోరుకునే వ్యక్తి తత్త్వాల స్వరూపాన్ని తెలుసుకోవడం అవసరమా? \n\nకంచెను విసిరేయాలనుకునే వ్యక్తికి దాన్ని విశ్లేషించాల్సిన అవసరం లేదు, అది ఏమిటో చూడాల్సిన అవసరం లేదు; అటువంటి వ్యక్తి ఆత్మను తెలుసుకోవాలనుకుంటే, తత్త్వాల సంఖ్యను లెక్కించడం లేదా వాటి లక్షణాలను తెలుసుకోవడం అవసరం లేదు; అతనికి చేయాల్సింది ఆత్మను దాచే తత్త్వాలను పూర్తిగా తిరస్కరించడం. ప్రపంచాన్ని కలలో కనిపించే స్వప్నంలా భావించాలి.\n\n22. మేల్కొనడం మరియు కలలో ఉండడం మధ్య ఎలాంటి తేడా లేదు?\n\nమేల్కొనడం పొడవుగా ఉంటుంది మరియు కల చిన్నది; దీనితో పాటు మరే తేడా లేదు. మేల్కొనేటప్పుడు జరిగే సంఘటనలు నిజంగా కనిపిస్తాయి, అలాగే కలలో ఉన్నప్పుడు కలలు కూడా నిజంగా కనిపిస్తాయి. కలలో మనస్సు మరో శరీరాన్ని స్వీకరిస్తుంది. మేల్కొనడం మరియు కలలో ఉన్నప్పుడు ఆలోచనలు, పేర్లు మరియు రూపాలు ఒకేసారి జరుగుతాయి. \n\n23. ముక్తి కోసం ఆకాంక్షించే వారికి పుస్తకాలు చదవడం ఏమైనా ప్రయోజనం ఉందా? \n\nఅన్ని గ్రంథాలు ముక్తి పొందాలంటే మనసును శాంతంగా ఉంచాలి అని చెబుతున్నాయి; అందువల్ల, వారి తుది ఉపదేశం మనసును శాంతంగా ఉంచడం. ఇది అర్థం చేసుకున్న తర్వాత, అంతకుముందు పుస్తకాలు చదవడం అవసరం లేదు. మనసును శాంతం చేయడానికి, మన స్వరూపం ఏమిటో మనలోనే ప్రశ్నించాలి; ఈ శోధన పుస్తకాల్లో ఎలా చేయబడుతుంది? మన స్వరూపాన్ని మన జ్ఞాన కంటితో తెలుసుకోవాలి. స్వరూపం ఐదు కవచాలలో ఉంది; కానీ పుస్తకాలు వాటి వెలుపల ఉన్నాయి. ఐదు కవచాలను వదిలి స్వరూపాన్ని తెలుసుకోవాలి కాబట్టి, పుస్తకాల్లో దానిని శోధించడం వ్యర్థం. మనం నేర్చుకున్న అన్ని విషయాలను మర్చిపోయే సమయం రానుంది. సంతోషం ఏమిటి? \n\nసంతోషం ఆత్మ యొక్క స్వభావమే; సంతోషం మరియు ఆత్మ వేరుగా ఉండవు. ప్రపంచంలోని ఏ వస్తువులోనూ సంతోషం లేదు. మనం అజ్ఞానంతో వస్తువుల నుండి సంతోషాన్ని పొందుతున్నామని ఊహిస్తున్నాము. మనసు బయటకు వెళ్లినప్పుడు, అది దుఃఖాన్ని అనుభవిస్తుంది. నిజానికి, దాని కోరికలు నెరవేరినప్పుడు, అది తన స్వస్థానానికి తిరిగి వచ్చి ఆత్మ యొక్క సంతోషాన్ని అనుభవిస్తుంది. అలాగే, నిద్ర, సమాధి మరియు మాయలో ఉన్నప్పుడు, కావలసిన వస్తువు పొందినప్పుడు లేదా ఇష్టంలేని వస్తువు తొలగించినప్పుడు, మనసు అంతర్గతంగా మారుతుంది మరియు శుద్ధమైన ఆత్మ-సంతోషాన్ని అనుభవిస్తుంది. ఈ విధంగా, మనసు విశ్రాంతి లేకుండా ఆత్మ నుండి బయటకు వెళ్లి, తిరిగి ఆత్మకు వస్తూ కదులుతుంది. చెట్టుకు కింద నీడ సుఖంగా ఉంటుంది; బయట తెరిచి ఉన్నప్పుడు వేడి కష్టంగా ఉంటుంది. సూర్యుని కింద తిరుగుతున్న వ్యక్తి నీడలో చేరినప్పుడు చల్లగా అనిపిస్తుంది. నీడ నుండి సూర్యునికి, అప్పుడు మళ్ళీ నీడలోకి వెళ్ళే వ్యక్తి మూర్ఖుడు. జ్ఞానవంతుడు శాశ్వతంగా నీడలోనే ఉంటాడు. అలాగే, సత్యాన్ని తెలిసిన వ్యక్తి మనస్సు బ్రహ్మనిని విడిచిపెట్టదు. అజ్ఞానుల మనస్సు, దానికంటే, ప్రపంచంలో తిరుగుతూ, దుఃఖాన్ని అనుభవించి, కొంత సమయం బ్రహ్మనికి తిరిగి ఆనందాన్ని పొందేందుకు వస్తుంది. వాస్తవానికి, ప్రపంచం అనేది కేవలం ఆలోచన మాత్రమే. ప్రపంచం కనిపించకుండా పోతే, అంటే ఆలోచన లేకపోతే, మనస్సు ఆనందాన్ని అనుభవిస్తుంది; మరియు ప్రపంచం కనిపిస్తే, అది దుఃఖాన్ని అనుభవిస్తుంది.\n\nజ్ఞానం-దృష్టి అంటే ఏమిటి? \n\nశాంతంగా ఉండటం అనేది జ్ఞానం-దృష్టి అని పిలువబడుతుంది. శాంతంగా ఉండటం అంటే ఆత్మలో మనస్సును స్థిరపరచడం. టెలిపతి, గత, వర్తమానం మరియు భవిష్యత్తు సంఘటనలను తెలుసుకోవడం మరియు క్లైర్వాయన్స్ జ్ఞానం-అవగాహనను ఏర్పరచవు. \n\n26. ఆకాంక్షలేని మనస్సు మరియు జ్ఞానం మధ్య సంబంధం ఏమిటి? \n\nఆకాంక్షలేని మనస్సు జ్ఞానం. ఈ రెండు వేరు కాదు; ఇవి ఒకటే. ఆకాంక్షలేని మనస్సు ఏ వస్తువుకు మనస్సును మలచడం నుండి దూరంగా ఉండటం. జ్ఞానం అంటే ఏ వస్తువును చూడకపోవడం. మరి ఇతరమైనది అన్వేషించడం కాకుండా ఆత్మను మాత్రమే చూడడం అంటే విరక్తి లేదా ఆకాంక్షలేని మనస్సు; ఆత్మను విడిచిపెట్టకపోవడం అంటే జ్ఞానం. \n\n27. పరిశోధన మరియు ధ్యానం మధ్య తేడా ఏమిటి? \n\nపరిశోధన అంటే మనస్సును ఆత్మలో నిలుపుకోవడం. ధ్యానం అంటే one\'s self బ్రహ్మనని, ఉనికిని-చైతన్యాన్ని-ఆనందాన్ని అనుకోవడం. \n\n28. ముక్తి అంటే ఏమిటి?\n\nబంధంలో ఉన్న one\'s self యొక్క స్వభావాన్ని అన్వేషించడం మరియు one\'s true natureని తెలుసుకోవడం ముక్తి. శ్రీ రామనార్పణం అస్తు.'
    ),
    Article(
        heading: 'ఆత్మ మరియు అనాత్మ - మహర్షి రమణ',
        body: 'అస్తిత్వం లేదా చైతన్యం మాత్రమే నిజమైన వాస్తవం. చైతన్యం మరియు మేల్కొనడం కలిస్తే మేల్కొనడం అని పిలుస్తాము. చైతన్యం మరియు నిద్ర కలిస్తే నిద్ర అని పిలుస్తాము. చైతన్యం మరియు కల కలిస్తే కల అని పిలుస్తాము. చైతన్యం అనేది అన్ని చిత్రాలు వచ్చి పోయే తెర. ఈ తెర నిజమైనది, చిత్రాలు కేవలం దానికి పైపైకి పడే నీడలు. ఆత్మ మరియు అందులోని రూపాలు, రశ్మి లోని పాము వంటి, ఈ విధంగా బాగా వివరించవచ్చు. ఒక తెర ఉంది. ఆ తెరపై మొదట రాజు యొక్క రూపం కనిపిస్తుంది. అతను సింహాసనంపై కూర్చుంటాడు. తరువాత ఆ mesma తెరపై వివిధ రూపాలు మరియు వస్తువులతో ఒక నాటకం ప్రారంభమవుతుంది, మరియు తెరపై ఉన్న రాజు ఆ నాటకాన్ని చూస్తాడు. చూడటం మరియు చూడబడటం కేవలం ఆ తెరపై ఉన్న నీడలు, ఇది మాత్రమే నిజమైన వాస్తవం, అన్ని చిత్రాలను మద్దతు ఇస్తుంది. ప్రపంచంలో కూడా, దర్శనకర్త మరియు దర్శనమయ్యే వస్తువు కలిసి మనస్సును ఏర్పరుస్తాయి, మరియు మనస్సు ఆత్మపై ఆధారపడి ఉంటుంది. అజాత పాఠశాల ఆడ్వైతం చెబుతుంది, \'ఒకే వాస్తవం తప్ప మరొకటి లేదు. జననం లేదా మరణం లేదు, ప్రక్షేపణం లేదా ఆహరణం లేదు, సాధకుడు లేదు, ముక్తి పొందాలని కోరుకునే ముక్తుడు లేదు, ముక్తుడు లేదు, బంధనం లేదు, ముక్తి లేదు. ఒకే ఒక్క ఐక్యత శాశ్వతంగా ఉంది. ఈ సత్యాన్ని grasp చేయడం కష్టంగా భావించే వారికి, \'మనం చుట్టూ ఉన్న ఈ దృఢమైన ప్రపంచాన్ని ఎలా పక్కన పెట్టగలం?\' అని అడిగితే, కలల అనుభవాన్ని సూచిస్తారు మరియు వారికి చెబుతారు, \'మీరు చూసే అన్ని విషయాలు దర్శనకర్తపై ఆధారపడి ఉన్నాయి.\' "చూసే వ్యక్తి తప్ప మరేను లేదు." దీనిని దృష్టి-సృష్టి వాదం అంటారు, అంటే ఒకరు మొదట తన మనసులో సృష్టించి, ఆ తరువాత తన మనసు సృష్టించినది చూడటం. ఇది అర్థం చేసుకోలేని వారికి, "కలల అనుభవం చాలా చిన్నది, కానీ ప్రపంచం ఎప్పుడూ ఉంటుంది. కలల అనుభవం నాకు మాత్రమే పరిమితమైంది. కానీ ప్రపంచాన్ని నేను మాత్రమే కాదు, ఎంతో మంది అనుభవిస్తారు మరియు అటువంటి ప్రపంచాన్ని不存在 అని చెప్పలేము" అని వాదించే వారికి, సృష్టి-దృష్టి వాదం గురించి మాట్లాడి, "దేవుడు మొదట అటువంటి అటువంటి వస్తువును అటువంటి అటువంటి మూలకాండ నుండి సృష్టించాడు, తరువాత ఇంకోది మరియు తదితరంగా" అని చెప్పబడుతుంది. అది మాత్రమే వారికి సంతృప్తిని ఇస్తుంది. వారి మనసులు ఇతర విధంగా సంతృప్తి చెందవు మరియు వారు తమను తాము అడుగుతారు, ‘అన్ని భూగోళాలు, అన్ని పటాలు, అన్ని శాస్త్రాలు, నక్షత్రాలు, గ్రహాలు మరియు వాటిని నియమించు లేదా సంబంధం కలిగిన నియమాలు మరియు అన్ని జ్ఞానం పూర్తిగా అబద్ధం ఎలా కావచ్చు?’ అటువంటి వారికి చెప్పడం మంచిది, ‘అవును. దేవుడు ఈ అన్ని సృష్టించాడు కాబట్టి మీరు దీన్ని చూస్తున్నారు.’ ఇవన్నీ వినేవారి సామర్థ్యానికి అనుగుణంగా మాత్రమే ఉన్నాయి.\n\nఅబ్సొల్యూట్ కేవలం ఒకటే కావచ్చు.\n\nమొదట, దీని గురించి చెప్పాలంటే, ఆత్మ యొక్క తెల్ల కాంతి ఉంది, ఇది కాంతి మరియు చాయలను మించిపోయింది. ఇందులో ఎలాంటి వస్తువులు కనిపించవు. చూడువాడు లేదా చూడబడినది లేదు. అప్పుడు పూర్తిగా చాయ (అవిద్య) కూడా ఉంది, అందులో ఎలాంటి వస్తువులు కనిపించవు. కానీ ఆ ఆత్మ నుండి ఒక ప్రతిబింబిత కాంతి ఉద్భవిస్తుంది, అది శుద్ధ మేధస్సు (మనసు) యొక్క కాంతి, మరియు ఈ కాంతి ద్వారా ప్రపంచంలోని అన్ని చిత్రాల ఉనికి కోసం స్థలం ఏర్పడుతుంది, ఇది పూర్తిగా కాంతిలో లేదా పూర్తిగా చీకటిలో కనిపించదు, కానీ కేవలం మృదువైన లేదా ప్రతిబింబిత కాంతిలో మాత్రమే కనిపిస్తుంది. జ్ఞాన (జ్ఞానం) లేదా వాస్తవం యొక్క దృష్టికోణం నుండి, ప్రపంచంలో కనిపించే బాధ ఖచ్చితంగా ఒక కల, అలాగే ప్రపంచం కూడా, అందులో ఆకలి వంటి ప్రత్యేకమైన బాధ అనేది అక్షయ భాగం. కలలో కూడా మీరు ఆకలిని అనుభవిస్తారు.\n\nమీరు ఇతరులను ఆకలితో బాధపడుతున్నట్లు చూస్తారు. మీరు మీకు తినిస్తారు, మరియు దయతో ఆకలితో బాధపడుతున్న ఇతరులను తినిపిస్తారు. కల కొనసాగుతున్నంత కాలం, ఆ అన్ని బాధలు మీరు ఇప్పుడు ప్రపంచంలో ఉన్న బాధను ఎలా భావిస్తున్నారో అంతే నిజంగా ఉన్నాయి. మీరు మేల్కొన్నప్పుడు మాత్రమే, కలలో ఉన్న నొప్పి అసత్యమని మీరు తెలుసుకున్నారు. మీరు పూర్తిగా తినేసి నిద్రపోయి ఉండవచ్చు. మీరు కష్టపడుతూ, పొద్దు నుండి రాత్రి వరకు కఠినమైన సూర్యుడి కింద పనిచేస్తున్నారని కలలో కల్పించుకుంటారు, మీరు అలసిపోయి, ఆకలిగా ఉంటారు మరియు చాలా తినాలనుకుంటారు. అప్పుడు మీరు మేల్కొనగానే మీ కడుపు నిండిపోయిందని, మీరు మీ మంచం నుండి బయటకు రాలేదని కనుగొంటారు. కానీ మీరు కలలో ఉన్నప్పుడు మీరు అనుభవిస్తున్న నొప్పి నిజం కాదని మీరు వ్యవహరించలేరు. కలలో ఉన్న ఆకలిని కలలో ఉన్న ఆహారంతో తీర్చాలి. మీరు కలలో చూసిన ఆకలితో ఉన్న మిత్రులకు ఆ కలలో ఆహారం అందించాలి. మీరు కల మరియు మేల్కొన్న స్థితులను ఎప్పుడూ కలిపి చూడలేరు. మీరు జ్ఞాన స్థితికి చేరుకునే వరకు మరియు మాయ నుండి మేల్కొనే వరకు, మీరు ఎక్కడైనా బాధను చూసినప్పుడు దాన్ని ఉపశమనం చేయడం ద్వారా సామాజిక సేవ చేయాలి. కానీ అహంకారంతో, అంటే \'నేను చేసే వ్యక్తి\' అనే భావనతో కాకుండా, \'నేను ప్రభువుని సాధన\' అనే భావనతో చేయాలి. అలాగే, \'నేను నా కంటే దిగువ ఉన్న వ్యక్తికి సహాయం చేస్తున్నాను. అతనికి సహాయం అవసరం. నేను సహాయం చేయగల స్థితిలో ఉన్నాను. నేను ఉన్నతుడిని, అతను దిగువవాడు\' అని ఆలోచించడం ద్వారా గర్వపడకూడదు. కానీ మీరు ఆ వ్యక్తికి సహాయం చేయాలి, అది ఆ వ్యక్తిలో దేవుని పూజ చేయడం యొక్క ఒక మార్గం. ఇలాంటి అన్ని సేవలు ఆత్మ కోసం, ఇతరుల కోసం కాదు. మీరు ఇతరులకు సహాయం చేయడం లేదు, కానీ కేవలం మీకు మాత్రమే. కైవల్య నవనీత పుస్తకం మాయపై ఆరు ప్రశ్నలను అడిగి, సమాధానమిచ్చింది. అవి ఉపదేశకరమైనవి:\n\n1. మాయ అంటే ఏమిటి? సమాధానం: ఇది అనిర్వచనీయమైనది లేదా వివరణాత్మకంగా చెప్పలేనిది. ఇది ఎవరికీ వస్తుంది? సమాధానం: ఇది తనను విడిగా ఉన్న వ్యక్తిగా భావించే మనసుకు లేదా అహంకారానికి వస్తుంది, ‘నేను ఇది చేస్తాను’ లేదా ‘ఇది నాది’ అని ఆలోచించే వారికి. \n\nఇది ఎక్కడి నుంచి వస్తుంది మరియు ఇది ఎలా ఉత్పన్నమైంది? సమాధానం: ఎవ్వరూ చెప్పలేరు. \n\nఇది ఎలా ఉత్పన్నమైంది? సమాధానం: అన్వేషణ లేకుండా, ‘నేను ఎవరు?’ అని అడగకపోవడం ద్వారా. \n\nఆత్మ మరియు మాయ రెండూ ఉంటే, ఇది అద్వైత సిద్ధాంతాన్ని అప్రామాణికం చేస్తుందా? సమాధానం: అవును, అది అప్రామాణికం కావాల్సిన అవసరం లేదు, ఎందుకంటే మాయ ఆత్మపై ఆధారపడి ఉంది, చిత్రములు తెరపై ఉన్నట్లుగా. చిత్రం తెర నిజమైనదిగా ఉన్నంతవరకు నిజమైనది కాదు. \n\nఆత్మ మరియు మాయ ఒకటైతే, ఆత్మ మాయ యొక్క స్వభావం కలిగి ఉంది మరియు అది కూడా మాయగా ఉందని వాదించలేమా? సమాధానం: కాదు, ఆత్మ మాయగా లేకుండా మాయను ఉత్పత్తి చేయగలదు. ఒక మాయాకారుడు మన వినోదం కోసం ప్రజలు, జంతువులు మరియు వస్తువుల మాయను సృష్టించవచ్చు, మరియు మేము అతన్ని ఎంత స్పష్టంగా చూస్తామో అంతే స్పష్టంగా వాటిని కూడా చూస్తాము, కానీ ప్రదర్శన తర్వాత అతనే మాత్రమే మిగిలి ఉంటాడు మరియు అతను సృష్టించిన అన్ని దృశ్యాలు అంతరించిపోతాయి.\n\nఅతను దృశ్యానికి భాగం కాదు, కానీ స్థిరమైన మరియు నిజమైనది.\n\nపుస్తకాలు సృష్టిని వివరించడానికి ఈ ఉదాహరణను ఉపయోగిస్తాయి: ఆత్మ ఒక చిత్రానికి కెన్వాస్ లాంటిది. మొదట, కెన్వాస్‌లో ఉన్న చిన్న రంధ్రాలను మూసివేయడానికి పేస్ట్ రాసి ఉంటుంది. ఈ పేస్ట్ అన్ని సృష్టిలోని అంతర్యామిని పోల్చవచ్చు. తరువాత, కళాకారుడు కెన్వాస్‌పై ఒక రూపాన్ని వేస్తాడు. ఇది అన్ని జీవుల సూక్ష్మ శరీరానికి పోల్చవచ్చు; ఉదాహరణకు, అన్ని వస్తువులు ఉద్భవించే కాంతి మరియు శబ్దం (బిందు మరియు నాద) లాంటిది. ఈ రూపరేఖలో కళాకారుడు రంగులతో తన చిత్రాన్ని వేస్తాడు, ఇది ప్రపంచాన్ని ఏర్పరచే ఘన రూపాలకు సమానంగా ఉంటుంది. వెదాంతం చెప్తుంది कि విశ్వం దృక్షకుడు తో సమానంగా కనిపిస్తుంది. దశల లేదా అడుగుల ద్వారా సృష్టి లేదు. ఇది కలలో సృష్టి వంటి, అనుభవించే వ్యక్తి మరియు అనుభవించే వస్తువులు ఒకేసారి ఉనికిలోకి వస్తాయి. ఈ వివరణతో సంతృప్తి చెందని వారికి, పుస్తకాల్లో క్రమబద్ధమైన సృష్టి సిద్ధాంతాలను అందిస్తారు. శంకర స్కూల్‌కు చెందిన అద్వైతవాదులు ప్రపంచం యొక్క ఉనికిని అంగీకరించరు లేదా దాన్ని అసత్యంగా అంటారని చెప్పడం కచ్చితంగా సరైనది కాదు. ఇంకా, ఇది ఇతరులకు కంటే వారికి మరింత నిజమైనది. వారి ప్రపంచం ఎప్పుడూ ఉంటుంది, అయితే ఇతర పాఠశాలల ప్రపంచానికి ఉత్పత్తి, వృద్ధి మరియు క్షయం ఉంటుంది, కాబట్టి అది నిజంగా ఉండదు. వారు \'ప్రపంచం\' అని చెప్పినప్పుడు అది నిజం కాదు, కానీ బ్రహ్మన్‌గా ప్రపంచం నిజం. అన్నీ బ్రహ్మన్, బ్రహ్మన్ తప్ప మరేమీ లేదు, మరియు బ్రహ్మన్‌గా ప్రపంచం నిజం. \n\nఆత్మ అనేది ఎప్పుడూ ఉండే ఒకే ఒక్క వాస్తవం, మరియు అన్ని ఇతర విషయాలను చూడటానికి ఆ ఆత్మ యొక్క కాంతి ద్వారా మాత్రమే అవి కనిపిస్తాయి. మేము దీన్ని మరచి, రూపంపై కేంద్రీకరించుకుంటాము. హాల్‌లో కాంతి వ్యక్తులు ఉన్నప్పుడు మరియు లేనప్పుడు, వారు ఏదైనా ప్రదర్శిస్తున్నప్పుడు, నాటకంలో, మరియు ఏదీ ప్రదర్శించబడకపోతే కూడా వెలుగుతుంది. ఇది హాల్‌ను, వ్యక్తులను మరియు నాటకాన్ని చూడటానికి మాకు సహాయపడే కాంతి. మనం వెలుగుతో ప్రదర్శించబడిన వస్తువులు లేదా రూపాలలో అంతగా మునిగిపోయి ఉంటాము, అందువల్ల ఆ వెలుగుపై మన దృష్టి ఉండదు. వస్తువులు కనిపించే మేల్కొనడం లేదా కలల స్థితిలో, మరియు మనం ఏమీ చూడని నిద్ర స్థితిలో, ఎప్పుడూ చైతన్య లేదా ఆత్మ యొక్క వెలుగు ఉంటుంది, అది ఎప్పుడూ వెలిగిస్తున్న హాల్ లాంప్ లాంటిది. చూడేవారిపై కేంద్రీకరించాలి, చూడబడిన వాటిపై కాదు, వస్తువులపై కాదు, వాటిని ప్రదర్శించే వెలుగుపై కేంద్రీకరించాలి.\n\nప్రపంచం యొక్క వాస్తవం గురించి, మరియు ప్రపంచంలో బాధ లేదా చెడు యొక్క ఉనికిని గురించి అడిగిన ప్రశ్నలు, ‘నేను ఎవరు?’ అని విచారించినప్పుడు మరియు చూడేవారిని కనుగొన్నప్పుడు అన్ని ఆగిపోతాయి. చూడేవారు లేకుండా, ప్రపంచం మరియు అందులో ఉన్న చెడులు ఉన్నట్లు చెప్పబడినవి ఉండవు.\n\nప్రపంచం ఐదు భావోద్వేగ వస్తువుల రూపంలో ఉంది, మరియు మరే ఇతర రూపంలో లేదు. ఈ ఐదు రకాల వస్తువులను ఐదు ఇంద్రియాలు గ్రహిస్తాయి. ఇవన్నీ ఈ ఐదు ఇంద్రియాల ద్వారా మనస్సు ద్వారా గ్రహించబడుతున్నందున, ప్రపంచం అనేది మనస్సు మాత్రమే. మనస్సు నుండి వేరుగా ఉన్న ప్రపంచం ఉందా? \n\nప్రపంచం మరియు చైతన్యం కలిసి ఉద్భవించి, కలిసే క్రమంలో, ప్రపంచం చైతన్యంతో మాత్రమే మెరిసి లేదా గ్రహించబడుతుంది. ఈ రెండు ఉద్భవించి, కలిసే మూలం, ఇది స్వయంగా కనిపించని మరియు కనుమరుగైనది కాదు, అది సంపూర్ణ వాస్తవం. \n\nఅన్ని జ్ఞానం మరియు కార్యకలాపాల మూలమైన మనస్సు మృదువుగా ఉంటే, ప్రపంచ దృష్టి ఆగిపోతుంది. నిజమైన దోకాణం గురించి తెలిసినప్పుడు, పాము అనే ఊహా భావన మాయమవ్వకముందు ఆ జ్ఞానం వెలుగులోకి రాదు. అంతేకాక, సృష్టి యొక్క అబద్ధ దృష్టిని విడిచిపెట్టకపోతే, నిజమైన అనుభవాన్ని పొందడం సాధ్యం కాదు.\n\nనిజంగా ఉన్నది కేవలం ఆత్మ మాత్రమే. ప్రపంచం, జీవ (వ్యక్తిగత ఆత్మ) మరియు ఇశ్వర (దేవుడు) అన్నవి మానసిక సృష్టులు, ముత్యాలలో వెండి యొక్క రూపం లాంటివి. ఇవన్నీ ఒకేసారి కనిపిస్తాయి మరియు ఒకే విధంగా మాయమవుతాయి. ఆత్మ మాత్రమే ప్రపంచం, అహంకారం మరియు ఇశ్వర.\n\nజ్ఞానికి ప్రపంచం కనిపిస్తుందా లేదా అనేది ప్రాధాన్యం లేదు. అది కనిపిస్తుందా లేదా, అతని దృష్టి ఎప్పుడూ ఆత్మ మీదే ఉంటుంది. అక్షరాలు మరియు వాటిపై ముద్రించిన కాగితాన్ని తీసుకోండి.\n\nమీరు పూర్తిగా అక్షరాలలో మునిగిపోయారు మరియు కాగితానికి దృష్టి మిగిలి లేదు. కానీ జ్ఞాని కాగితం మాత్రమే నిజమైన ఆధారం అని భావిస్తాడు, అక్షరాలు కనిపిస్తున్నాయా లేదా అన్నది పరిగణనలోకి తీసుకోకుండా. మీరు వివిధ పదార్థాల నుండి వివిధ ఆకారాల్లో అన్ని రకాల మిఠాయిలను తయారు చేస్తారు, అవి అన్ని తీపిగా ఉంటాయి ఎందుకంటే అందులో చక్కెర ఉంది, మరియు తీపితనం చక్కెర యొక్క స్వభావం. అలాగే, అన్ని అనుభవాలు మరియు వాటి లేకపోవడం ఆత్మ యొక్క స్వభావం అయిన ప్రకాశాన్ని కలిగి ఉంటాయి. ఆత్మ లేకుండా అవి అనుభవించబడవు, చక్కెర లేకుండా మీరు తయారు చేసే వస్తువులలో ఒక్కటి కూడా తీపిగా ఉండదు. \n\nస్వభావంలో ఉన్న సత్యాన్ని ఇశ్వరుడు అంటారు. ఇమానెన్స్ కేవలం మాయతోనే ఉండవచ్చు. అది (ఇశ్వరుడు) మాయతో కూడిన సత్యం యొక్క జ్ఞానం. సూక్ష్మ అహంకారం నుండి హిరణ్యగర్భుడు ఉద్భవిస్తాడు; హిరణ్యగర్భుడి నుండి స్థూల, కంక్రీటు విరాట్ ఉద్భవిస్తుంది. చిత్-ఆత్మ కేవలం శుద్ధమైన సత్యం. ప్రపంచంలో బాధ యొక్క ఉనికి గురించి, జ్ఞాని తన అనుభవం నుండి వివరిస్తాడు, వ్యక్తి ఆత్మలో అంతరంగం చేసుకుంటే అన్ని బాధలు ముగుస్తాయి. వస్తువు స్వయంతో భిన్నంగా ఉన్నంతకాలం బాధ అనుభవించబడుతుంది. కానీ ఆత్మ ఒక విభజన రహిత సమగ్రతగా కనుగొనబడినప్పుడు, అనుభవించడానికి ఎవరు మరియు ఏమి ఉంది?  \nఉపనిషత్తు గ్రంథం \'నేనే బ్రహ్మ\' అంటే బ్రహ్మ \'నేనే\' అని ఉనికిలో ఉన్నది.'
    ),
    Article(
        heading: 'మహర్షి రామణుల ద్వారా యోగా యొక్క ఎనిమిది అవయవాలు',
        body: 'D: జ్ఞాన అష్టాంగం అంటే ఏమిటి? \n\nM: జ్ఞాన అష్టాంగం అంటే ఇప్పటికే ప్రస్తావించిన ఎనిమిది అవయవాలు, అంటే యమ, నియమ మొదలైనవి, కానీ వేరుగా నిర్వచించబడ్డవి:\n\n(1) యమ: ఇది ఇంద్రియాల సమాహారాన్ని నియంత్రించడం, శరీరం వంటి ప్రపంచంలో ఉన్న లోపాలను గ్రహించడం.\n\n(2) నియమ: ఇది ఆత్మకు సంబంధించి మానసిక మోడ్స్ యొక్క ప్రవాహాన్ని కొనసాగించడం మరియు వ్యతిరేక మోడ్స్‌ను తిరస్కరించడం. ఇంకా చెప్పాలంటే, ఇది పరమాత్మ కోసం నిరంతరం ఉద్భవించే ప్రేమను సూచిస్తుంది.\n\n(3) ఆసన: ఇది బ్రహ్మనుపై నిరంతర ధ్యానం సులభంగా చేయడానికి సహాయపడేది.\n\n(4) ప్రాణాయామ: రేచక (వాయువు విడుదల) అనేది ప్రపంచాన్ని, శరీరాన్ని మొదలైన వాటిని ఏర్పరచే నామం మరియు రూపం అనే రెండు అసత్య అంశాలను తొలగించడం, పూరక (వాయువు శ్వాస) అనేది ఆ వస్తువుల్లో నిరంతరం ఉండే మూడు నిజమైన అంశాలను, అస్తిత్వం, చైతన్యం మరియు ఆనందం, గ్రహించడం, మరియు కుంభక అనేది అలా గ్రహించిన అంశాలను నిలిపివేయడం.\n\n(5) ప్రత్యాహార: ఇది తొలగించిన నామం మరియు రూపం మళ్లీ మనస్సులోకి ప్రవేశించకుండా అడ్డుకోవడం.\n\n(6) ధరణ: ఇది మనస్సును హృదయంలో నిలిపి ఉంచడం, బయటకు వెళ్ళకుండా ఉండటం, మరియు ఒకరు అస్తిత్వం-చైతన్యం-ఆనందం అనే స్వయమే అని గ్రహించడం.\n\n(7) ధ్యాన: ఇది ‘నేను కేవలం శుద్ధ చైతన్యం’ అనే రూపంలో ధ్యానం. అంటే, ఐదు కవచాలనుంచి ఏర్పడిన శరీరాన్ని విడిచిపెట్టిన తర్వాత, "నేను ఎవరు?" అని ప్రశ్నిస్తారు, మరియు ఆ ప్రశ్నకు ఫలితంగా, \'నేను\'గా ఉండి, ఆత్మగా ప్రకాశిస్తుంది. ఈ విజ్ఞానం స్వయంగా కాకుండా, స్వయం లేదా అస్వయం సంబంధితంగా మాత్రమే ప్రकटమవుతుంది. ఇది స్వయానికి సంబంధించినప్పుడు, దీనిని నిజమైన జ్ఞానం అంటారు, ఇది ఆత్మను లక్ష్యంగా చేసుకున్న మానసిక మోడ్ రూపంలో ఉన్న జ్ఞానం, లేదా ఏకీకృత (ఆత్మ) విషయాన్ని కలిగి ఉన్న జ్ఞానం; మరియు ఇది అస్వయానికి సంబంధించినప్పుడు, దీనిని అజ్ఞానం అంటారు. ఈ విజ్ఞాన స్థితి, ఇది స్వయం సంబంధితంగా ఉండి ఆత్మ యొక్క రూపంగా ప్రకాశిస్తే, దీనిని \'నేను-ప్రకటన\' అని అంటారు. ఈ ప్రకటన నిజమైన (అంటే, ఆత్మ) నుండి వేరుగా జరగదు. ఇది నిజమైన అనుభవానికి ముద్రగా పనిచేసే ప్రదర్శన. అయితే, ఇది స్వతంత్రంగా నిజమైన స్థితిని ఏర్పరచలేరు. ఈ ప్రదర్శన జరిగే ఆధారం, ప్రాథమిక వాస్తవం, ప్రజ్ఞానంగా కూడా పిలవబడుతుంది. వేదాంత గ్రంథం ‘ప్రజ్ఞానం బ్రహ్మ’ అదే సత్యాన్ని బోధిస్తుంది. \n\nఈ విషయాన్ని శాస్త్రం యొక్క ఉద్దేశ్యంగా తెలుసుకోండి. స్వయంకాంతి మరియు అన్ని విషయాలకు సాక్షిగా ఉన్న ఆత్మ, విజ్ఞానకోశంలో (బుద్ధి యొక్క కవచం) నివసిస్తున్నట్లు ప్రదర్శించబడుతుంది. \n\nభావనాత్మక మోడ్ ద్వారా, ఈ ఆత్మను మీ లక్ష్యంగా స్వీకరించండి మరియు ఆ ఆత్మగా ఆనందించండి.'
    ),
  ],
);
